// v0.59.2 · Web: en el Balance, cada cuenta de una partida desplegada dice en qué sublínea se presenta; versión 0.59.2.
// Uso (desde la carpeta frontend, después de aplicar-v0592.mjs):   node aplicar-v0592-web.mjs
import fs from 'node:fs'
import path from 'node:path'

const FICHEROS = {"package.json": "{\n  \"name\": \"minierp-frontend\",\n  \"private\": true,\n  \"version\": \"0.59.2\",\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"lint\": \"eslint .\",\n    \"preview\": \"vite preview\",\n    \"test\": \"vitest run\"\n  },\n  \"dependencies\": {\n    \"@supabase/supabase-js\": \"^2.118.0\",\n    \"lucide-react\": \"^1.66.0\",\n    \"react\": \"^19.3.1\",\n    \"react-dom\": \"^19.3.1\",\n    \"xlsx\": \"https://cdn.sheetjs.com/xlsx-0.20.3/xlsx-0.20.3.tgz\"\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^10.0.1\",\n    \"@types/react\": \"^19.2.18\",\n    \"@types/react-dom\": \"^19.2.7\",\n    \"@vitejs/plugin-react\": \"^6.1.2\",\n    \"eslint\": \"^10.14.0\",\n    \"eslint-plugin-react-hooks\": \"^7.1.1\",\n    \"eslint-plugin-react-refresh\": \"^0.5.6\",\n    \"globals\": \"^17.13.0\",\n    \"vite\": \"^8.3.5\",\n    \"vitest\": \"^5.0.5\"\n  },\n  \"overrides\": {\n    \"minimatch\": \"11.0.3\"\n  }\n}\n", "src/anomalies.js": "// SALDOS AL REVÉS EN EL BALANCE (v0.57.0 · ADR 0057): el ERP no compensa una cuenta con saldo contrario a su naturaleza\n// (un proveedor deudor, una caja acreedora…): la presenta en la otra masa del balance y avisa. La base de datos dice en\n// qué partida cae cada una (erp.fs_line_anomalies); aquí se cuenta cuántas hay en cada partida y en las que la contienen.\n//   rows: las partidas del Balance ({ code, parent }) · anomalies: [{ line_code, account_no, severity, … }]\n//   → { <partida>: { n, errors } }, también en las partidas superiores (Existencias → Activo corriente → Total activo)\nexport function anomalyCounts(rows, anomalies) {\n  const parent = new Map((rows ?? []).map((r) => [r.code, r.parent]))\n  const out = {}\n  for (const a of anomalies ?? []) {\n    const seen = new Set()\n    for (let code = a.line_code; code && !seen.has(code); code = parent.get(code)) {\n      seen.add(code)\n      const c = (out[code] ??= { n: 0, errors: 0 })\n      c.n += 1\n      if (a.severity === 'error') c.errors += 1\n    }\n  }\n  return out\n}\n\n// Las cuentas con saldo al revés, por número de cuenta (para marcarlas al desplegar una partida)\nexport const anomalyByAccount = (anomalies) => new Map((anomalies ?? []).map((a) => [a.account_no, a]))\n\n// v0.59.2 · Al desplegar una partida que tiene sublíneas (II. Deudas a corto plazo), sus cuentas salen todas juntas:\n// a cada una se le dice en qué sublínea se presenta (1. Deudas con entidades de crédito). null si es la misma partida.\nexport function accountSubLine(account, lineCode, rows) {\n  if (!account?.line_code || account.line_code === lineCode) return null\n  return rows.find((r) => r.code === account.line_code) ?? null\n}\n", "src/components/FinancialStatements.jsx": "import { Fragment, useEffect, useState } from 'react'\nimport { supabase } from '../supabase'\nimport { useI18n } from '../i18n'\nimport { workDate, workYear } from '../workDate'\nimport { money } from '../format'\nimport { changePct, prevCutoff } from '../compare'\nimport ErrorBox from './ErrorBox'\nimport ReportActions from './ReportActions'\nimport { downloadXlsx, fileName } from '../exportXlsx'\nimport DateField from './DateField'\nimport MonthPicker from './MonthPicker'\nimport SimulationToggle, { SimulationBanner } from './SimulationToggle'\nimport { moveToYear, reportBase, simTitle } from '../reportPeriod'\nimport { accountSubLine, anomalyByAccount, anomalyCounts } from '../anomalies'\nimport { companyPath } from '../router'\nimport Link from './Link'\n\n// Balance de situación y Cuenta de Pérdidas y Ganancias (modelo PYMES del PGC)\n//   statement: 'balance' | 'pyg' · columnas ejercicio actual y anterior, como en las cuentas anuales\n// v0.30.0 · ANÁLISIS HORIZONTAL: variación en importe y en % frente al ejercicio anterior, y el anterior también al\n// desplegar una partida. Con fecha de corte (0032): la PyG se compara con el mismo periodo del año anterior y el\n// Balance con el cierre del ejercicio anterior (NIC 34). La variación no lleva color: que suba un gasto o un ingreso\n// no es \"bueno\" o \"malo\" por sí solo; el signo y el % bastan para ver dónde mirar.\n// v0.51.0 · «hasta» con la fecha rápida y los botones de mes, y la simulación con los asientos en edición (ADR 0051).\n// v0.57.0 · SALDOS AL REVÉS (ADR 0057): el ERP no compensa; en el Balance avisa con una franja, un ⚠ en cada partida\n// que contiene alguna cuenta al revés y, al desplegarla, el ⚠ y la nota de la cuenta (erp.fs_line_anomalies).\nexport default function FinancialStatements({ company, statement }) {\n  const { t, language } = useI18n()\n  const [years, setYears] = useState([])\n  const [year, setYear] = useState(() => workYear(company))   // año de la fecha de trabajo\n  const [toDate, setToDate] = useState('')\n  const [hideZero, setHideZero] = useState(true)\n  const [sim, setSim] = useState(false)          // simulación: incluir los asientos en edición\n  const [rows, setRows] = useState([])\n  const [open, setOpen] = useState({})           // partida → cuentas que la forman (drill-down)\n  const [error, setError] = useState('')\n  const [anomalies, setAnomalies] = useState([])  // v0.57.0: cuentas con saldo al revés y su partida\n\n  useEffect(() => {\n    supabase.from('fiscal_years').select('year').eq('company_id', company.id).order('year')\n      .then(({ data, error }) => {\n        if (error) return setError(error.message)\n        setYears(data.map((r) => r.year))\n        if (data.length && !data.some((r) => r.year === Number(year))) setYear(data[data.length - 1].year)\n      })\n  }, [company.id])\n\n  useEffect(() => {\n    setOpen({})\n    supabase.rpc('financial_statement', {\n      p_company: company.id, p_year: Number(year), p_statement: statement, p_to_date: toDate || null, p_drafts: sim,\n    }).then(({ data, error }) => (error ? setError(error.message) : (setError(''), setRows(data))))\n    if (statement !== 'balance') return   // solo el Balance lleva el aviso (abajo, «shown»)\n    supabase.rpc('fs_line_anomalies', { p_company: company.id, p_year: Number(year), p_to: toDate || null, p_drafts: sim })\n      .then(({ data, error }) => setAnomalies(error ? [] : data ?? []))   // el aviso no debe impedir ver el Balance\n  }, [company.id, year, toDate, statement, sim])\n\n  // Las cuentas anuales muestran los negativos entre paréntesis: (1.234,00)\n  const m = (v) => (Number(v) < 0 ? `(${money(-v, language)})` : money(v, language))\n  const label = (r) => (language === 'en' ? r.label_en : r.label)\n\n  // ¿Hay ejercicio anterior? Si no, no se enseñan sus columnas (estarían a cero y confundirían)\n  const hasPrev = years.includes(Number(year) - 1)\n  // Fecha de corte del ejercicio anterior: Balance → su cierre (null); PyG → la misma fecha un año antes\n  const prevDate = prevCutoff(statement, toDate)\n  const shortDate = (d) => new Date(`${d}T00:00:00`).toLocaleDateString(language === 'en' ? 'en-GB' : 'es-ES')\n\n  async function toggle(code) {\n    if (open[code]) return setOpen({ ...open, [code]: null })\n    const ask = (y, d) => supabase.rpc('fs_line_accounts', {\n      p_company: company.id, p_year: y, p_statement: statement, p_code: code, p_to_date: d, p_drafts: sim,\n    })\n    const [now, before] = await Promise.all([ask(Number(year), toDate || null),\n      hasPrev ? ask(Number(year) - 1, prevDate) : Promise.resolve({ data: [] })])\n    if (now.error || before.error) return setError((now.error || before.error).message)\n    // Una fila por subcuenta con los dos importes (puede existir solo en uno de los dos ejercicios)\n    const byAccount = new Map()\n    for (const a of now.data) byAccount.set(a.account_no, { ...a, amount_prev: 0 })\n    for (const a of before.data) {\n      const row = byAccount.get(a.account_no)\n      if (row) row.amount_prev = a.amount\n      else byAccount.set(a.account_no, { ...a, amount: 0, amount_prev: a.amount })\n    }\n    setOpen({ ...open, [code]: [...byAccount.values()].sort((a, b) => a.account_no.localeCompare(b.account_no)) })\n  }\n\n  // Variación: importe y % sobre el valor absoluto del anterior (si el anterior es 0, el % no tiene sentido)\n  const diff = (r) => Number(r.amount) - Number(r.amount_prev)\n  const pct = (r) => changePct(r.amount, r.amount_prev, language)\n\n  // Excel: las partidas visibles con su sangría, los dos ejercicios y la variación (números, no texto)\n  const title = simTitle(statement === 'balance' ? t('balanceSheet') : t('incomeStatement'), sim, t('sim.prefix'))\n  const filters = `${t('year')} ${year}${toDate ? ` · ${t('fsAt').replace('{d}', shortDate(toDate))}` : ''}`\n  const exportExcel = () => downloadXlsx({\n    title: `${title} · ${company.name ?? ''}`, subtitle: filters, sheet: title,\n    file: fileName(title, company.name, year, toDate),\n    columns: [\n      { header: t('fsLine'), key: 'label', type: 'text', width: 60 },\n      { header: String(year), key: 'amount', type: 'money' },\n      ...(hasPrev ? [\n        { header: String(Number(year) - 1), key: 'amount_prev', type: 'money' },\n        { header: t('fsChange'), key: 'change', type: 'money' },\n        { header: '%', key: 'pct', type: 'pct' },\n      ] : []),\n    ],\n    rows: visible.map((r) => ({\n      label: `${'   '.repeat(r.level)}${label(r)}`, amount: r.amount, amount_prev: r.amount_prev, change: diff(r),\n      pct: Math.abs(Number(r.amount_prev)) < 0.005 ? null : diff(r) / Math.abs(Number(r.amount_prev)),\n    })),\n  })\n\n  const amount = (code) => Number(rows.find((r) => r.code === code)?.amount ?? 0)\n  const difference = statement === 'balance' ? amount('ACT') - amount('PNP') : 0\n  const shown = statement === 'balance' ? anomalies : []\n  const marks = anomalyCounts(rows, shown)\n  const byAccount = anomalyByAccount(shown)\n  const errors = shown.filter((a) => a.severity === 'error').length\n  const visible = rows.filter((r) => !hideZero || r.is_total || Number(r.amount) !== 0 || Number(r.amount_prev) !== 0)\n\n  return (\n    <section className=\"tarjeta\">\n      <div className=\"titulo-informe\">\n        <h2>{statement === 'balance' ? t('balanceSheet') : t('incomeStatement')}</h2>\n        {rows.length > 0 && <ReportActions onExcel={exportExcel} info={`${sim ? `${t('sim.prefix')} · ` : ''}${company.name} · ${filters}`} />}\n      </div>\n      <p className=\"ayuda\">{statement === 'balance' ? t('balanceSheetHelp') : t('incomeStatementHelp')}</p>\n      <div className=\"rejilla-tres\">\n        <label>{t('year')}\n          <select value={year} onChange={(e) => { setYear(e.target.value); setToDate(moveToYear(toDate, e.target.value)) }}>\n            {years.map((y) => <option key={y} value={y}>{y}</option>)}\n          </select>\n        </label>\n        <label>{t('toDate')}\n          <DateField value={toDate} onChange={setToDate} company={company} label={t('toDate')} clearable monthHint={false}\n                     baseDate={reportBase(toDate, year, workDate(company))} />\n        </label>\n        <div className=\"opciones-informe\">\n          <label className=\"opcion\">\n            <input type=\"checkbox\" checked={hideZero} onChange={(e) => setHideZero(e.target.checked)} /> {t('hideZeroLines')}\n          </label>\n          <SimulationToggle value={sim} onChange={setSim} />\n        </div>\n      </div>\n      <MonthPicker year={year} value={toDate} onChange={setToDate} />\n      <SimulationBanner company={company} year={year} toDate={toDate} value={sim} />\n      <ErrorBox error={error} company={company} />\n\n      {statement === 'balance' && rows.length > 0 && (\n        <div className={Math.abs(difference) < 0.005 ? 'cuadre ok' : 'cuadre descuadre'}>\n          <span>{t('totalAssets')}: {m(amount('ACT'))}</span>\n          <span>{t('totalEquityLiabilities')}: {m(amount('PNP'))}</span>\n          <strong>{Math.abs(difference) < 0.005 ? `✓ ${t('balanced')}` : `${t('difference')}: ${m(difference)}`}</strong>\n        </div>\n      )}\n\n      {shown.length > 0 && (\n        <p className=\"aviso-reves\" role=\"note\">\n          ⚠ {t(shown.length === 1 ? 'reverse.one' : 'reverse.many').replace('{n}', shown.length)}\n          {errors > 0 && <strong> {t('reverse.errors').replace('{n}', errors)}</strong>}\n          {' '}{t('reverse.why')}{' '}\n          <Link to={companyPath(company.id, 'checks')} className=\"enlace\">{t('reverse.go')}</Link>\n        </p>\n      )}\n\n      {/* En el móvil la tabla se desplaza en horizontal: con tabindex se puede mover también con el teclado */}\n      <div className=\"tabla-ancha\" tabIndex={0} role=\"region\"\n           aria-label={statement === 'balance' ? t('balanceSheet') : t('incomeStatement')}>\n        <table className=\"estado\">\n          <thead>\n            <tr>\n              <th />\n              <th className=\"num\">{year}{toDate && <small>{t('fsAt').replace('{d}', shortDate(toDate))}</small>}</th>\n              {hasPrev && <>\n                <th className=\"num\">{Number(year) - 1}\n                  <small>{prevDate ? t('fsAt').replace('{d}', shortDate(prevDate)) : toDate ? t('fsClosing') : ''}</small>\n                </th>\n                <th className=\"num\">{t('fsChange')}</th>\n                <th className=\"num\">%</th>\n              </>}\n            </tr>\n          </thead>\n          <tbody>\n            {visible.map((r) => (\n              <Fragment key={r.code}>\n                <tr className={`${r.is_total ? 'total-estado' : 'partida'} nivel-${r.level}`}\n                    onClick={() => !r.is_total && toggle(r.code)}>\n                  <td style={{ paddingLeft: `${8 + r.level * 14}px` }}>\n                    {!r.is_total && <span className=\"desplegar\">{open[r.code] ? '▾' : '▸'}</span>} {label(r)}\n                    {marks[r.code] && (\n                      <span className={`marca-reves${marks[r.code].errors ? ' error' : ''}`}\n                            title={t('reverse.line').replace('{n}', marks[r.code].n)}>\n                        {' '}⚠ {marks[r.code].n}<span className=\"oculto\"> {t('reverse.line').replace('{n}', marks[r.code].n)}</span>\n                      </span>\n                    )}\n                  </td>\n                  <td className=\"num\">{m(r.amount)}</td>\n                  {hasPrev && <>\n                    <td className=\"num anterior\">{m(r.amount_prev)}</td>\n                    <td className=\"num variacion\">{Math.abs(diff(r)) < 0.005 ? '' : m(diff(r))}</td>\n                    <td className=\"num variacion\">{pct(r)}</td>\n                  </>}\n                </tr>\n                {open[r.code]?.map((a) => (\n                  <tr key={`${r.code}-${a.account_no}`} className=\"cuenta-partida\">\n                    <td style={{ paddingLeft: `${28 + r.level * 14}px` }}>\n                      <span className=\"codigo\">{a.account_no}</span>\n                      {language === 'en' ? a.account_name_en || a.account_name : a.account_name}\n                      {accountSubLine(a, r.code, rows) && (\n                        <small className=\"sublinea\"> → {label(accountSubLine(a, r.code, rows))}</small>\n                      )}\n                      {byAccount.get(a.account_no) && (\n                        <small className={`nota-reves${byAccount.get(a.account_no).severity === 'error' ? ' error' : ''}`}>\n                          ⚠ {t(byAccount.get(a.account_no).severity === 'error' ? 'reverse.accountError' : 'reverse.account')}\n                          {' '}{language === 'en' ? byAccount.get(a.account_no).note_en || byAccount.get(a.account_no).note : byAccount.get(a.account_no).note}\n                        </small>\n                      )}\n                    </td>\n                    <td className=\"num\">{m(a.amount)}</td>\n                    {hasPrev && <>\n                      <td className=\"num anterior\">{m(a.amount_prev)}</td>\n                      <td className=\"num variacion\">{Math.abs(diff(a)) < 0.005 ? '' : m(diff(a))}</td>\n                      <td className=\"num variacion\">{pct(a)}</td>\n                    </>}\n                  </tr>\n                ))}\n                {open[r.code]?.length === 0 && (\n                  <tr key={`${r.code}-vacio`} className=\"cuenta-partida\"><td colSpan={hasPrev ? 5 : 2} className=\"ayuda\">{t('noAccountsInLine')}</td></tr>\n                )}\n              </Fragment>\n            ))}\n          </tbody>\n        </table>\n      </div>\n      {hasPrev && <p className=\"ayuda\">{t(statement === 'balance' ? 'fsCompareBalance' : 'fsComparePyg')}</p>}\n      <p className=\"ayuda\">{t('statementsNote')}</p>\n    </section>\n  )\n}", "src/index.css": ":root {\n  --fondo: #f5f6f8; --tarjeta: #ffffff; --texto: #1d2330; --suave: #5b6475;\n  --primario: #1f5eff; --borde: #d9dde5; --aviso: #b42318;\n  font-family: system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  color: var(--texto); background: var(--fondo);\n}\n@media (prefers-color-scheme: dark) {\n  :root { --fondo: #12151c; --tarjeta: #1b1f29; --texto: #e8eaf0; --suave: #9aa3b5;\n          --borde: #2c3240; --primario: #6d8dff; --aviso: #ff8a80; }\n}\n* { box-sizing: border-box; }\nbody { margin: 0; }\nmain { max-width: 640px; margin: 0 auto; padding: 16px; }\nh1 { font-size: 1.4rem; }\nh2 { font-size: 1.1rem; margin: 0 0 12px; }\n.cabecera { display: flex; justify-content: space-between; align-items: center; gap: 12px; }\n.cabecera select { width: auto; }\n.tarjeta { background: var(--tarjeta); border: 1px solid var(--borde); border-radius: 12px;\n           padding: 16px; margin-bottom: 16px; display: flex; flex-direction: column; gap: 10px; }\ninput, select, button { font: inherit; padding: 10px 12px; border-radius: 8px;\n                        border: 1px solid var(--borde); background: var(--tarjeta); color: var(--texto); }\nbutton { background: var(--primario); color: var(--sobre-color); border: none; cursor: pointer; }\nbutton.secundario { background: transparent; color: var(--primario); border: 1px solid var(--primario); }\n.fila { display: flex; gap: 10px; }\n.fila button { flex: 1; }\nul { list-style: none; padding: 0; margin: 0; }\nli { display: flex; flex-direction: column; padding: 10px 0; border-bottom: 1px solid var(--borde); }\nli span { color: var(--suave); font-size: .9rem; }\n.usuario { display: flex; justify-content: space-between; align-items: center; color: var(--suave); }\n.aviso { color: var(--aviso); }\n/* --- Bloque F: empresa, cuentas, asientos, libro diario --- */\n.clicable { cursor: pointer; }\n.clicable:hover strong { color: var(--primario); }\n.ayuda { color: var(--suave); font-size: .85rem; margin: 0; }\n.exito { color: var(--exito); }\n.empresa-cabecera { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }\n.empresa-cabecera div { display: flex; flex-direction: column; }\n.empresa-cabecera span { color: var(--suave); font-size: .85rem; }\n.pestanas { display: flex; gap: 6px; margin-bottom: 16px; overflow-x: auto; }\n.pestanas button { background: transparent; color: var(--texto); border: 1px solid var(--borde); white-space: nowrap; }\n.pestanas button.activa { background: var(--primario); color: var(--sobre-color); border-color: var(--primario); }\n.codigo { font-family: ui-monospace, Consolas, monospace; color: var(--suave); margin-right: 6px; }\n.cuentas { max-height: 60vh; overflow-y: auto; }\n.cuentas li { flex-direction: row; gap: 6px; padding: 6px 0; }\n.cuentas li.nivel-1 { font-weight: 700; }\n.cuentas li.nivel-2 { font-weight: 600; padding-left: 8px; }\n.cuentas li.nivel-3 { padding-left: 16px; }\n.cuentas li.nivel-4 { padding-left: 24px; }\n.cuentas li.subcuenta { padding-left: 32px; color: var(--primario); }\nlabel { display: flex; flex-direction: column; gap: 4px; font-size: .85rem; color: var(--suave); }\n.rejilla-cabecera { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }   /* v0.41.1: minmax(0, …) para que un desplegable largo no desborde el móvil */\n.rejilla-cabecera > *, .rejilla-cabecera select, .rejilla-cabecera input { min-width: 0; max-width: 100%; }\n.linea { display: grid; grid-template-columns: 1fr 1fr auto; gap: 6px; padding: 8px 0; border-bottom: 1px dashed var(--borde); }\n.linea select { grid-column: 1 / -1; }\n.linea input { min-width: 0; }\n.acciones-linea { display: flex; gap: 4px; }\n.acciones-linea button { padding: 8px 10px; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\n.totales { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; padding: 10px 12px; border-radius: 8px; font-size: .9rem; }\n.totales.ok { background: rgba(26,127,55,.06); color: var(--exito); }\n.totales.descuadre { background: rgba(180,35,24,.10); color: var(--aviso); }\n.asiento { border-top: 1px solid var(--borde); padding-top: 10px; }\n.asiento header { display: flex; justify-content: space-between; color: var(--suave); font-size: .9rem; }\n.asiento header strong { color: var(--texto); }\n.concepto { margin: 4px 0 8px; }\ntable { width: 100%; border-collapse: collapse; font-size: .9rem; }\nth { text-align: left; color: var(--suave); font-weight: 500; border-bottom: 1px solid var(--borde); padding: 4px; }\ntd { padding: 4px; border-bottom: 1px solid var(--borde); vertical-align: top; }\n.num { text-align: right; white-space: nowrap; }\n\n/* --- Bloque G: demo y límites --- */\n.insignia { display: inline-block; font-size: .7rem; font-weight: 700; letter-spacing: .05em;\n            padding: 2px 6px; border-radius: 999px; background: var(--alerta-fondo); color: #1d2330; vertical-align: middle; }\n.solo-lectura { background: rgba(245,165,36,.15); color: var(--texto); padding: 8px 12px; border-radius: 8px; font-size: .9rem; }\n.publicar { margin: 0 0 12px; }\n\n/* --- Bloque H: importación CSV --- */\n.boton-archivo { flex: 1; display: flex; align-items: center; justify-content: center; cursor: pointer;\n                 background: var(--primario); color: var(--sobre-color); border-radius: 8px; padding: 10px 12px; font-size: 1rem; }\n.tabla-scroll { max-height: 50vh; overflow: auto; }\n.roles .rol-celda { text-align: center; }   /* v0.58.0 · qué puede hacer cada rol */\ntr.estado-insert td:last-child strong { color: var(--exito); }\ntr.estado-update td:last-child strong { color: var(--alerta); }\ntr.estado-error td:last-child strong { color: var(--aviso); }\ntr.estado-error { background: rgba(180,35,24,.06); }\n\n/* --- Asiento rápido con teclado --- */\n.cuenta-linea { grid-column: 1 / -1; display: flex; flex-direction: column; gap: 2px; }\n.nombre-cuenta { font-size: .8rem; color: var(--suave); min-height: 1em; padding-left: 4px; }\ninput.invalido { border-color: var(--aviso); }\n\n/* --- J1: terceros --- */\n.opciones { display: flex; flex-direction: column; gap: 6px; }\n.opcion { flex-direction: row; align-items: center; gap: 8px; color: var(--texto); font-size: .95rem; }\n.opcion input { width: auto; }\n\n/* --- J2: configuración de impuestos --- */\n.impuestos { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 12px; }\n.impuestos li { display: flex; flex-direction: column; gap: 6px; border-top: 1px solid var(--borde); padding-top: 10px; }\n.impuestos li.bloqueado { opacity: .55; }\n.liquidacion { border-top: 2px solid var(--borde); margin-top: 14px; padding-top: 10px; }\n.liquidacion h3 { margin: 0 0 4px; font-size: 1rem; }\n.impuestos .rejilla-cabecera, .liquidacion .rejilla-cabecera { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }\n.impuestos select, .liquidacion select { min-width: 0; width: 100%; }\n\n\n/* --- J3: facturas --- */\n.linea-factura { display: grid; grid-template-columns: 1fr 1fr auto; gap: 6px; padding: 8px 0; border-bottom: 1px dashed var(--borde); }\n.linea-factura input, .linea-factura select { min-width: 0; }\n.reduce { color: var(--alerta); font-weight: 600; }\n.vista-previa { margin-top: 8px; }\nli .insignia { margin-left: 6px; }\n.factura .rejilla-cabecera { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }\n.factura select, .factura input { min-width: 0; width: 100%; }\n\n/* --- J4: liquidación --- */\n.rejilla-tres { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }\n.rejilla-tres select { min-width: 0; width: 100%; }\n.liquidacion-borrador h3 { margin: 14px 0 4px; font-size: 1rem; }\ntr.total td { font-weight: 700; border-top: 2px solid var(--borde); }\n.resultado { margin-top: 12px; }\ntr.resultado-payable td { color: var(--aviso); }\ntr.resultado-carry_forward td, tr.resultado-refund td { color: var(--exito); }\n.cuadre { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 12px; padding: 8px 12px; border-radius: 8px; font-size: .9rem; }\n.cuadre.ok { background: rgba(26,127,55,.10); }\n.cuadre.descuadre { background: rgba(180,35,24,.10); color: var(--aviso); }\nli.bloqueado { opacity: .55; }\n\n/* --- Bloque I: informes --- */\n.informe td { white-space: nowrap; }\n.informe td:first-child { white-space: normal; min-width: 160px; }\ntr.anomalia.warning td { background: rgba(245,165,36,.12); }\ntr.anomalia.error td { background: rgba(180,35,24,.12); color: var(--aviso); }\n.anomalias { list-style: none; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.anomalias li { display: flex; flex-direction: column; gap: 4px; border-left: 4px solid var(--alerta-fondo); padding: 6px 10px; }\n.anomalias li.error { border-left-color: var(--aviso); }\n.anomalias button { align-self: flex-start; }\n.insignia.error { background: var(--aviso); color: var(--sobre-color); }\n\n/* --- K1: menú agrupado por áreas --- */\n/* v0.41.1 · en el PC se usa todo el ancho, con un tope de 1600 px (en un monitor enorme la vista no se separa tanto\n   que haya que mover la cabeza). Los párrafos se quedan en ~90 caracteres por línea: más largos se leen peor. */\nmain:has(.empresa-layout) { max-width: 1600px; }\n.empresa-layout .tarjeta p, .empresa-layout p.ayuda { max-width: 90ch; }\n/* En una pantalla ancha (≥ 1320 px) dos tarjetas seguidas sin tabla van una al lado de la otra, en el orden de\n   lectura; las demás ocupan todo el ancho. Quién va emparejada lo decide src/wideLayout.js (clase «mitad»). */\n/* align-content: start: si el menú es más alto que el contenido (modo Auditor), las filas NO se estiran para igualarlo\n   (eso dejaba un hueco gris enorme bajo la ruta) */\n@media (min-width: 1320px) {\n  .empresa-contenido { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 16px; align-items: start; align-content: start; }\n  .empresa-contenido > * { grid-column: 1 / -1; }\n  .empresa-contenido > .mitad { grid-column: auto; }\n  /* Cierre del ejercicio: el asistente (los pasos) a la izquierda y el cierre a la derecha */\n  .empresa-contenido > .asistente-cierre:has(+ .cierre), .empresa-contenido > .asistente-cierre + .cierre { grid-column: auto; }\n}\n.empresa-layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 20px; }\n.boton-menu { display: flex; gap: 8px; align-items: center; background: var(--tarjeta); color: var(--texto);\n              border: 1px solid var(--borde); margin-bottom: 12px; text-align: left; }\n.boton-menu strong { color: var(--primario); }\n.menu-empresa { display: none; flex-direction: column; gap: 12px; background: var(--tarjeta); border: 1px solid var(--borde);\n                border-radius: 12px; padding: 12px; margin-bottom: 16px; }\n.menu-empresa.abierto { display: flex; }\n.menu-grupo { display: flex; flex-direction: column; gap: 2px; }\n.menu-grupo h3 { margin: 0 0 4px; font-size: .75rem; text-transform: uppercase; letter-spacing: .06em; color: var(--suave); }\n.menu-grupo button { background: transparent; color: var(--texto); text-align: left; padding: 8px 10px; }\n.menu-grupo button:hover { background: rgba(31,94,255,.08); }\n.menu-grupo button.activa { background: var(--primario); color: var(--sobre-color); }\n.menu-grupo button.secundario { color: var(--primario); border: 1px solid var(--primario); text-align: center; }\n.ruta { display: none; color: var(--suave); font-size: .85rem; margin: 0 0 10px; }\n@media (min-width: 900px) {\n  .empresa-layout { grid-template-columns: 220px minmax(0, 1fr); }\n  main:has(.empresa-layout) { padding: 16px 24px; }\n  .empresa-cabecera { grid-column: 1 / -1; }\n  .boton-menu { display: none; }\n  .menu-empresa { display: flex; position: sticky; top: 16px; align-self: start; }\n  .ruta { display: block; }\n}\n\n/* --- K2: diario con rango y anulación --- */\n.asiento { display: flex; flex-direction: column; }\n.asiento.anulado .concepto, .asiento.anulado table { opacity: .55; }\n.etiquetas { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }\n.etiqueta { font-size: .75rem; padding: 2px 8px; border-radius: 999px; background: rgba(31,94,255,.10); color: color-mix(in srgb, var(--primario) 80%, var(--texto)); }   /* v0.41.1: contraste AA también sobre su fondo */\n.etiqueta.anula { background: rgba(26,127,55,.12); color: var(--exito); }\n.etiqueta.anulado { background: rgba(180,35,24,.10); color: var(--aviso); }\nbutton.pequeno { align-self: flex-start; padding: 6px 10px; font-size: .85rem; margin-top: 6px; }\n.anular { display: flex; flex-direction: column; gap: 8px; margin-top: 8px; padding: 10px; border: 1px dashed var(--aviso); border-radius: 8px; }\n.anular input, .rejilla-tres input { min-width: 0; width: 100%; }\n\n/* --- K3: invitados --- */\n.invitado { display: flex; flex-direction: column; gap: 8px; border-top: 1px solid var(--borde); padding-top: 12px; margin-top: 4px; }\n.fila input { flex: 1; min-width: 0; }\n\n/* --- UX: selector de idioma con bandera --- */\n.idiomas { display: flex; border: 1px solid var(--borde); border-radius: 8px; overflow: hidden; }\n.idiomas button { display: flex; align-items: center; gap: 6px; background: var(--tarjeta); color: var(--suave);\n                  border: none; border-radius: 0; padding: 6px 10px; font-size: .85rem; }\n.idiomas button + button { border-left: 1px solid var(--borde); }\n.idiomas button.activo { background: rgba(31,94,255,.10); color: var(--texto); font-weight: 600; }\n.idiomas svg { width: 20px; height: 14px; border-radius: 2px; box-shadow: 0 0 0 1px rgba(0,0,0,.15); }\n/* --- UX: cabeceras de área del menú (no se pulsan), como las secciones de BC / SAP --- */\n.menu-empresa { padding: 8px; gap: 8px; }\n.menu-grupo h3 { margin: 0 0 2px; padding: 6px 10px; border-radius: 6px; background: var(--fondo);\n                 border-left: 3px solid var(--borde); cursor: default; user-select: none; }\n.menu-grupo button { margin-left: 8px; }\n/* v0.41.1 · acordeón: el título del área es un botón que abre su área y cierra las demás */\n.menu-grupo.acordeon h3 { padding: 0; }\n.menu-grupo button.titulo-grupo { margin: 0; width: 100%; display: flex; align-items: center; gap: 6px; padding: 6px 10px;\n  background: transparent; color: var(--suave); font: inherit; font-size: .75rem; font-weight: 700; text-transform: uppercase;\n  letter-spacing: .06em; border-radius: 6px; cursor: pointer; }\n.menu-grupo button.titulo-grupo:hover { background: rgba(31,94,255,.08); color: var(--texto); }\n.menu-grupo.acordeon.abierto button.titulo-grupo { color: var(--texto); }\n.punto-actual { margin-left: auto; color: var(--primario); font-size: .7rem; }\n.menu-botones { display: flex; flex-direction: column; gap: 2px; margin-top: 2px; }\n.menu-botones .menu-grupo { gap: 4px; }\n\n/* --- Estados financieros --- */\n.tabla-ancha { overflow-x: auto; }\n.estado { font-size: .9rem; }\n.estado td:first-child { white-space: normal; }\n.estado tr.partida { cursor: pointer; }\n.estado tr.partida:hover td { background: rgba(31,94,255,.06); }\n.estado tr.total-estado td { font-weight: 700; background: var(--fondo); }\n.estado tr.total-estado.nivel-0 td { border-top: 2px solid var(--texto); }\n.estado td.anterior { color: var(--suave); }\n.estado tr.cuenta-partida td { font-size: .8rem; color: var(--suave); border-bottom: none; }\n.estado tr.cuenta-partida .sublinea { font-style: italic; }   /* v0.59.2 · a qué sublínea va la cuenta */\n.desplegar { display: inline-block; width: 12px; color: var(--primario); }\n\n/* --- M: cierre del ejercicio --- */\n.insignia.cerrado { background: var(--suave); color: var(--tarjeta); }\n.ejercicio-cierre { max-width: 240px; }\n.pasos-cierre { list-style: none; padding: 0; margin: 12px 0; display: flex; flex-direction: column; gap: 6px; }\n.pasos-cierre > li { border-left: 3px solid var(--borde); padding: 2px 0 8px 12px; }\n.pasos-cierre h3 { margin: 0 0 4px; font-size: 1rem; }\n.pasos-cierre details summary { cursor: pointer; color: var(--primario); font-size: .9rem; margin: 4px 0; }\n.comprobaciones { list-style: none; padding: 0; margin: 4px 0; display: flex; flex-direction: column; gap: 4px; font-size: .9rem; }\n.comprobaciones li { display: block; padding: 4px 8px; border-radius: 6px; }\n.comprobaciones li.error { background: rgba(180,35,24,.10); color: var(--aviso); }\n.comprobaciones li.warning { background: rgba(245,165,36,.15); }\n.comprobaciones li.info { color: var(--suave); }\n.comprobaciones .icono { display: inline-block; width: 1.2em; font-weight: 700; }\n\n/* --- J5: retenciones y operaciones sin cuota --- */\n.linea-factura .causa-exencion { grid-column: 1 / -1; font-size: .8rem; color: var(--suave); }\n.retencion { margin-top: 8px; max-width: 420px; }\n\n.modelo-retenciones { margin-bottom: 12px; }\n.modelo-retenciones h3 { margin: 10px 0 4px; font-size: 1rem; }\n\n/* --- J5 parte 2: régimen de IVA y recargo --- */\n.regimen { margin-top: 10px; max-width: 460px; }\n.opcion.pequena { font-size: .85rem; margin-top: 4px; }\n\n/* --- Modo auditor: importar diario --- */\n.importar-diario h3 { margin: 14px 0 4px; font-size: 1rem; }\n.progreso { display: flex; flex-direction: column; gap: 4px; margin: 10px 0; font-size: .9rem; color: var(--suave); }\n.progreso progress { width: 100%; height: 10px; }\n\n/* --- Modo auditor: ratios --- */\n.ratios { list-style: none; padding: 0; margin: 8px 0 0; display: flex; flex-direction: column; }\n.ratios li { border-top: 1px solid var(--borde); }\n.ratio-fila { width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 12px; align-items: baseline;\n  background: transparent; color: var(--texto); border: 0; border-radius: 0; padding: 10px 4px; text-align: left; font-weight: 400; }\n.ratio-fila:hover { background: rgba(31,94,255,.06); }\n.ratio-nombre { grid-column: 1; }\n.ratio-valor { grid-column: 2; display: flex; gap: 8px; align-items: baseline; justify-content: flex-end; white-space: nowrap; }\n.ratio-anterior { grid-column: 2; text-align: right; font-size: .8rem; color: var(--suave); white-space: nowrap; }\n.ratio-estado { display: inline-block; font-size: .75rem; font-weight: 700; padding: 1px 8px; border-radius: 999px; }\n.ratio-estado.ok { background: rgba(26,127,55,.12); color: color-mix(in srgb, var(--exito) 80%, var(--texto)); }   /* v0.41.2: contraste AA sobre su fondo */\n.ratio-estado.low, .ratio-estado.high { background: rgba(245,165,36,.18); color: color-mix(in srgb, var(--alerta) 55%, var(--texto)); }\n.ratio-detalle { padding: 0 4px 12px 22px; display: flex; flex-direction: column; gap: 6px; font-size: .9rem; }\n.ratio-detalle p { margin: 0; }\n.leyenda-ratios { display: flex; flex-wrap: wrap; gap: 8px; margin: 10px 0 0; }\n@media (prefers-color-scheme: dark) {\n  .ratio-estado.ok { color: var(--exito); }\n  .ratio-estado.low, .ratio-estado.high { color: var(--alerta); }\n}\n\n/* --- Analista IA --- */\n.analista-ia { border-left: 4px solid var(--primario); }\n.analista-ia > button { align-self: flex-start; }\n.analisis { display: flex; flex-direction: column; gap: 12px; margin-top: 12px; }\n.resumen-ia { margin: 0; font-size: 1rem; line-height: 1.5; }\n.bloque-ia h3 { margin: 0 0 4px; font-size: .95rem; }\n.bloque-ia ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 6px; }\n.bloque-ia li { display: block; border: 0; padding: 0; line-height: 1.45; }\n.bloque-ia .icono { display: inline-block; width: 1.3em; font-weight: 700; }\n.bloque-ia.strengths .icono { color: var(--exito); }\n.bloque-ia.alerts .icono { color: var(--alerta); }\n.bloque-ia.auditor_questions .icono { color: var(--primario); }\n.bloque-ia.learning { background: rgba(31,94,255,.07); border-radius: 8px; padding: 10px 12px; }\n.bloque-ia.learning p { margin: 0; line-height: 1.45; }\n.ia-texto { white-space: pre-wrap; font-family: inherit; background: var(--fondo); padding: 10px; border-radius: 8px; }\n\n/* --- Tutor de asientos --- */\n.tutor-asientos { border-left: 4px solid #8250df; }\n.tutor-asientos textarea { width: 100%; font: inherit; padding: 10px; border: 1px solid var(--borde); border-radius: 8px;\n  background: var(--tarjeta); color: var(--texto); resize: vertical; box-sizing: border-box; }\n.tutor-asientos > button { align-self: flex-start; }\n.propuesta { display: flex; flex-direction: column; gap: 10px; }\n.propuesta h3 { margin: 6px 0 2px; font-size: .95rem; }\n.propuesta td .insignia { margin-left: 6px; }\n.propuesta > button { align-self: flex-start; }\n\n/* --- Accesos, Miembros y opiniones --- */\n.accesos { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; }\n.accesos li { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-direction: row;\n  border-top: 1px solid var(--borde); padding: 10px 0; }\n.accesos li > div { display: flex; flex-direction: column; gap: 2px; min-width: 0; }\n.accesos li strong { overflow-wrap: anywhere; }\n.alta-acceso { display: flex; flex-direction: column; gap: 8px; border-top: 2px solid var(--borde); padding-top: 12px; }\n.alta-acceso h3 { margin: 0; font-size: 1rem; }\n.alta-acceso button { align-self: flex-start; }\n.opiniones { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }\n.opiniones li { display: flex; flex-direction: column; gap: 6px; border-left: 4px solid var(--borde); padding: 6px 10px; }\n.opiniones li.correct { border-left-color: var(--exito); }\n.opiniones li.partial { border-left-color: var(--alerta); }\n.opiniones li.wrong { border-left-color: var(--aviso); }\n.opiniones p { margin: 0; }\n.cabecera-opinion { display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: baseline; }\nbutton.enlace { background: transparent; color: var(--primario); border: 0; padding: 0; align-self: flex-start; font-weight: 400; }\n.opinion-ia { display: flex; flex-direction: column; gap: 8px; border-top: 1px dashed var(--borde); padding-top: 10px; }\n.fila-opiniones { display: flex; flex-wrap: wrap; gap: 6px; }\n.fila-opiniones button.activa { background: var(--primario); color: var(--sobre-color); }\n.opinion-ia textarea { width: 100%; font: inherit; padding: 8px; border: 1px solid var(--borde); border-radius: 8px;\n  background: var(--tarjeta); color: var(--texto); box-sizing: border-box; }\n.opinion-ia > button { align-self: flex-start; }\n.titular { background: rgba(130,80,223,.10); padding: 8px 12px; border-radius: 8px; margin: 0 0 12px; }\n.mencion { font-size: .8rem; }\n.fila-usuario { display: flex; gap: 6px; flex-wrap: wrap; }\n.publicar-demo { border-left: 4px solid var(--alerta); }\n\n/* --- v0.25.0: rutas (empresas como enlaces) y deshacer línea --- */\n.enlace-empresa { display: flex; flex-direction: column; color: inherit; text-decoration: none; border-radius: 6px; }\n.enlace-empresa:hover strong, .enlace-empresa:focus-visible strong { color: var(--primario); }\n.enlace-empresa:focus-visible { outline: 2px solid var(--primario); outline-offset: 4px; }\n.deshacer { display: flex; align-items: center; gap: 10px; margin: 0; padding: 8px 12px; border-radius: 8px;\n            background: var(--fondo); border: 1px solid var(--borde); font-size: .9rem; }\n.deshacer button.enlace { padding: 0; }\n\n\n\n/* --- v0.25.0: Inicio, estados vacíos y de carga --- */\na.boton { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 10px 14px; border-radius: 8px;\n          background: var(--primario); color: var(--sobre-color); text-decoration: none; white-space: nowrap; }\na.boton.secundario { background: transparent; color: var(--primario); border: 1px solid var(--primario); }\na.enlace { color: var(--primario); text-decoration: none; }\na.enlace:hover { text-decoration: underline; }\n.cargando { color: var(--suave); }\n.cargando span { display: inline-block; animation: latido 1.2s ease-in-out infinite; }\n@keyframes latido { 50% { opacity: .2; } }\n@media (prefers-reduced-motion: reduce) { .cargando span { animation: none; } }\n.vacio { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 8px; padding: 16px 8px; }\n.vacio p { margin: 0; }\n.vacio-icono { font-size: 1.8rem; }\n.empresa-contenido { container-type: inline-size; }\n.inicio { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 16px; }\n@container (min-width: 760px) { .inicio { grid-template-columns: minmax(0, 1fr) 260px; } }\n.saludo h2 { margin: 0; }\n.ruta-cabecera { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }\n.ruta-cabecera h2 { margin: 0; }\n.progreso-texto { color: var(--suave); font-size: .9rem; white-space: nowrap; }\n.progreso { height: 8px; border-radius: 4px; background: var(--borde); overflow: hidden; }\n.progreso span { display: block; height: 100%; background: var(--exito); transition: width .3s; }\n.pasos { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 8px; }\n.paso { display: flex; flex-direction: row; align-items: center; gap: 12px; padding: 10px 12px;\n        border: 1px solid var(--borde); border-radius: 10px; }\n.paso-numero { flex: none; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center;\n               font-weight: 600; background: var(--borde); color: var(--texto); }\n.paso-texto { flex: 1; display: flex; flex-direction: column; gap: 2px; min-width: 0; }\n.paso-texto span { color: var(--suave); font-size: .88rem; }\n.paso.hecho .paso-numero { background: var(--exito); color: var(--sobre-color); }\n.paso.hecho .paso-texto strong { color: var(--suave); }\n.paso.siguiente { border: 2px solid var(--primario); background: color-mix(in srgb, var(--primario) 7%, var(--tarjeta)); }\n.paso.siguiente .paso-numero { background: var(--primario); color: var(--sobre-color); }\n/* v0.30.0: .paso.pendiente ya no lleva opacidad: bajaba el contraste de sus enlaces por debajo de 4,5:1 */\n@container (max-width: 520px) {\n  .paso { flex-wrap: wrap; }\n  .paso a.boton { margin-left: 42px; }\n  .paso.siguiente a.boton { width: calc(100% - 42px); }\n}\n.accesos-rapidos .acceso { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border: 1px solid var(--borde);\n                           border-radius: 8px; color: var(--texto); text-decoration: none; }\n.accesos-rapidos .acceso:hover, .accesos-rapidos .acceso:focus-visible { border-color: var(--primario); color: var(--primario); }\n.ultimos li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 10px; padding: 8px 0; }\n.ultimo-fecha { grid-column: 1 / -1; font-size: .8rem; }\n.ultimo-concepto { color: var(--texto) !important; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.ultimos .num { font-variant-numeric: tabular-nums; }\n\n/* --- v0.25.0: modo Básico / Auditor --- */\n.empresa-cabecera .modo { margin-left: auto; display: inline-flex; flex-direction: row; flex: none; border: 1px solid var(--borde); border-radius: 999px; padding: 3px; gap: 2px; }\n.empresa-cabecera .modo button { background: transparent; color: var(--suave); padding: 6px 14px; border-radius: 999px; font-size: .9rem; }\n.empresa-cabecera .modo button.activo { background: var(--primario); color: var(--sobre-color); }\n.menu-grupo button small { display: block; font-size: .75rem; color: var(--suave); margin-top: 1px; }\n.menu-grupo button.activa small { color: var(--sobre-color); }\n.aviso-modo { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; margin: 0 0 12px; padding: 8px 12px; border-radius: 8px;\n              background: var(--fondo); border: 1px dashed var(--borde); color: var(--suave); font-size: .9rem; }\n.aviso-modo button.enlace { padding: 0; }\n@media (max-width: 600px) {\n  .empresa-cabecera { flex-wrap: wrap; }\n  .empresa-cabecera .modo { margin-left: 0; }\n}\n\n/* --- v0.25.0: aviso global \"Cargando…\" (cualquier consulta a Supabase de más de 0,3 s) --- */\n.ocupado { position: fixed; top: 0; left: 0; right: 0; z-index: 50; pointer-events: none; }\n.ocupado-barra { display: block; height: 3px; background: linear-gradient(90deg, transparent, var(--primario), transparent);\n                 background-size: 50% 100%; background-repeat: no-repeat; animation: barra 1.1s linear infinite; }\n.ocupado-texto { position: absolute; top: 8px; right: 12px; padding: 4px 10px; border-radius: 999px; font-size: .8rem;\n                 background: var(--tarjeta); color: var(--suave); border: 1px solid var(--borde); }\n@keyframes barra { from { background-position: -50% 0; } to { background-position: 150% 0; } }\n@media (prefers-reduced-motion: reduce) { .ocupado-barra { animation: none; background: var(--primario); opacity: .5; } }\n.exito a.enlace { font-weight: 500; }\n.aviso a.enlace { white-space: nowrap; }\n\n/* --- v0.26.0: errores en lenguaje claro --- */\n.caja-error { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; margin: 8px 0; padding: 10px 14px;\n              border-radius: 8px; border: 1px solid var(--aviso); border-left-width: 4px;\n              background: color-mix(in srgb, var(--aviso) 6%, var(--tarjeta)); }\n.caja-error p { margin: 0; }\n.caja-error-titulo { color: var(--aviso); font-weight: 600; }\n.caja-error-pista { color: var(--texto); font-size: .92rem; }\n.caja-error a.boton { padding: 6px 12px; font-size: .9rem; }\n.caja-error details { font-size: .8rem; color: var(--suave); }\n.caja-error summary { cursor: pointer; }\n.caja-error code { display: block; margin-top: 4px; white-space: pre-wrap; word-break: break-word; }\n\n/* --- v0.26.0: pantalla de entrada --- */\n.entrada { display: flex; flex-direction: column; gap: 16px; }\n.entrada-portada { display: flex; flex-direction: column; gap: 10px; }\n.entrada-portada h2 { font-size: 1.45rem; line-height: 1.25; margin: 0; }\n.entrada-sub { margin: 0; color: var(--suave); }\n.entrada-puntos { display: flex; flex-direction: column; gap: 8px; }\n.entrada-puntos li { flex-direction: row; align-items: flex-start; gap: 10px; padding: 0; border: 0; }\n.entrada-puntos li > span { font-size: 1.25rem; line-height: 1.3; }\n.entrada-puntos li div { display: flex; flex-direction: column; }\n.entrada-puntos li div span { font-size: .88rem; }\n.boton-demo { font-size: 1.05rem; padding: 14px 18px; font-weight: 600; }\n.pestanas-acceso { display: flex; border-bottom: 1px solid var(--borde); margin: -4px 0 4px; }\n.pestanas-acceso button { flex: 1; background: transparent; color: var(--suave); border-radius: 0; border-bottom: 3px solid transparent; }\n.pestanas-acceso button.activa { color: var(--primario); border-bottom-color: var(--primario); font-weight: 600; }\n.entrada-acceso form { display: flex; flex-direction: column; gap: 8px; }\n.entrada-acceso label { font-size: .9rem; font-weight: 500; margin-top: 4px; }\n.campo-password { display: flex; gap: 8px; }\n.campo-password input { flex: 1; min-width: 0; }\n.campo-password button { flex: none; }\n.requisito { margin: 0; font-size: .85rem; color: var(--suave); }\n.requisito.ok { color: var(--exito); }\n.enviado { display: flex; flex-direction: column; gap: 8px; }\n.enviado p { margin: 0; }\n.entrada-pie { text-align: center; color: var(--suave); font-size: .85rem; padding-bottom: 16px; }\n.entrada-pie p { margin: 4px 0; }\n.entrada-pie a { color: var(--primario); }\n\n/* --- v0.26.0: plantillas de asientos y buscador de cuentas --- */\n.plantillas { display: flex; flex-direction: column; gap: 6px; padding: 10px 12px; border-radius: 10px;\n              background: var(--fondo); border: 1px solid var(--borde); }\n.plantillas-titulo { font-weight: 600; }\n.plantillas-botones { display: flex; flex-wrap: wrap; gap: 6px; }\n.plantillas-botones button { padding: 6px 10px; font-size: .9rem; }\n.explica { font-size: .9rem; }\n.explica summary { cursor: pointer; color: var(--primario); }\n.explica p { margin: 6px 0 0; color: var(--texto); line-height: 1.45; }\n.cuenta-linea { position: relative; }\n.sugerencias { position: absolute; z-index: 20; left: 0; right: 0; top: 44px; max-height: 260px; overflow-y: auto;\n               background: var(--tarjeta); border: 1px solid var(--borde); border-radius: 8px; box-shadow: 0 6px 20px rgba(0,0,0,.15); }\n.sugerencias li { flex-direction: row; gap: 8px; padding: 8px 10px; cursor: pointer; border-bottom: 1px solid var(--borde); font-size: .92rem; }\n.sugerencias li:last-child { border-bottom: 0; }\n.sugerencias li.activa, .sugerencias li:hover { background: color-mix(in srgb, var(--primario) 12%, var(--tarjeta)); }\ninput.esperado { border-color: var(--primario); box-shadow: inset 0 0 0 1px var(--primario); }\n/* v0.41.1 · asiento en una línea: el importe propuesto en gris (placeholder) y la papelera */\ninput.propuesto::placeholder { color: var(--primario); opacity: .75; font-style: italic; }\n.linea input[inputmode=\"decimal\"] { text-align: right; font-variant-numeric: tabular-nums; }\n.papelera { background: transparent; color: var(--suave); border: 0; padding: 6px; align-self: center; line-height: 0; }\n.papelera:hover, .papelera:focus-visible { color: var(--aviso); background: color-mix(in srgb, var(--aviso) 10%, transparent); }\n.cabecera-lineas { display: none; }\n.cabecera-asiento { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n.cabecera-asiento .concepto-asiento { grid-column: 1 / -1; }\n@media (min-width: 700px) {\n  /* PC: una fila por línea · Cuenta (con su nombre al lado) | Debe | Haber | papelera */\n  .lineas-asiento .linea { grid-template-columns: minmax(0, 1fr) 9.5em 9.5em 2.2em; align-items: center; padding: 3px 0; }\n  .lineas-asiento .cuenta-linea { grid-column: auto; flex-direction: row; align-items: center; gap: 8px; }\n  .lineas-asiento .cuenta-linea input { width: 13em; flex: none; }\n  .lineas-asiento .nombre-cuenta { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding: 0; }\n  .lineas-asiento .cabecera-lineas { display: grid; padding: 0 0 2px; border-bottom: 1px solid var(--borde); color: var(--suave); font-size: .8rem; }\n  .lineas-asiento .cabecera-lineas span:nth-child(2), .lineas-asiento .cabecera-lineas span:nth-child(3) { text-align: right; padding-right: 10px; }\n  .papelera { opacity: 0; }\n  .linea:hover .papelera, .linea:focus-within .papelera, .papelera:focus-visible { opacity: 1; }\n  .cabecera-asiento { grid-template-columns: 12.5em 10em minmax(0, 1fr); }\n  .cabecera-asiento .concepto-asiento { grid-column: auto; }\n}\n\n\n/* --- v0.27.0: glosario (ⓘ con globo y página) --- */\n.cabecera-acciones { display: flex; align-items: center; gap: 10px; }\n.enlace-glosario { color: var(--primario); text-decoration: none; font-size: .9rem; white-space: nowrap; }\n.enlace-glosario:hover { text-decoration: underline; }\n.termino { position: relative; display: inline-flex; align-items: baseline; gap: 2px; }\n.termino-i { background: transparent; color: var(--primario); border: 0; padding: 0 2px; font-size: .85em; line-height: 1; cursor: help; }\n.termino-i:focus-visible { outline: 2px solid var(--primario); border-radius: 4px; }\n.globo { position: absolute; z-index: 40; top: calc(100% + 6px); left: 0; width: max-content; max-width: min(320px, calc(100vw - 32px));\n         display: flex; flex-direction: column; gap: 4px; padding: 10px 12px; border-radius: 10px; text-align: left;\n         background: var(--tarjeta); color: var(--texto); border: 1px solid var(--borde); box-shadow: 0 8px 24px rgba(0,0,0,.18);\n         font-size: .88rem; font-weight: 400; line-height: 1.4; white-space: normal; text-transform: none; letter-spacing: normal; }\n.globo strong { font-size: .95rem; }\n.globo-ejemplo { display: block; color: var(--suave); font-style: italic; margin-top: 2px; }\n.globo-erp { display: block; color: var(--suave); font-size: .8rem; margin-top: 2px; }\n.globo a.enlace { font-size: .85rem; }\n.glosario .fila-glosario { display: flex; align-items: center; gap: 12px; }\n.glosario .fila-glosario h2 { margin: 0; }\n.glosario dl { margin: 0; display: flex; flex-direction: column; }\n.glosario-termino { padding: 10px 0; border-bottom: 1px solid var(--borde); }\n.glosario-termino dt { font-weight: 600; }\n.glosario-termino dd { margin: 2px 0 0; line-height: 1.45; }\n.oculto { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n@media (max-width: 480px) { .enlace-glosario { font-size: 0; } .enlace-glosario::first-letter { font-size: 1.2rem; } }\n/* --- v0.27.0: colores de estado con versión oscura (contraste ≥ 4,5:1) y foco visible común --- */\n:root { --exito: #1a7f37; --alerta: #9a6700; --alerta-fondo: #f5a524; --error: var(--aviso); --sobre-color: #ffffff; }\n@media (prefers-color-scheme: dark) {\n  :root { --exito: #4ac26b; --alerta: #e3b341; --sobre-color: #0d1220; }   /* texto oscuro sobre los colores claros del modo oscuro */\n}\n:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 2px solid var(--primario); outline-offset: 2px; }\np a.enlace, .ayuda a.enlace, .aviso a.enlace, .entrada-pie a { text-decoration: underline; text-underline-offset: 2px; }\n.icono-svg { flex: none; vertical-align: -3px; }\n\n/* --- v0.27.0: iconos (lucide-react) --- */\n.enlace-glosario { display: inline-flex; align-items: center; gap: 4px; }\n.entrada-icono { flex: none; color: var(--primario); margin-top: 2px; }\n.vacio-icono { color: var(--suave); }\n.accesos-rapidos .acceso .icono-svg { color: var(--primario); }\n.plantillas-botones button { display: inline-flex; align-items: center; gap: 6px; }\n.caja-error-titulo { display: flex; align-items: flex-start; gap: 6px; }\n.caja-error-titulo .icono-svg { margin-top: 2px; }\n.boton-demo { display: inline-flex; align-items: center; justify-content: center; gap: 8px; }\nform.tarjeta > label { font-size: .9rem; font-weight: 500; margin-bottom: -4px; }\n\n/* --- v0.28.0: CAPTCHA (Turnstile) y demo destacada al llegar con ?demo --- */\n.captcha { min-height: 65px; display: flex; justify-content: center; }\n.captcha-espera { text-align: center; }\n.boton-demo.resaltado { box-shadow: 0 0 0 4px color-mix(in srgb, var(--primario) 35%, transparent); }\n\n/* --- v0.29.0: borrar la empresa (zona de peligro) --- */\n.zona-peligro { border-left: 4px solid var(--aviso); }\n.zona-peligro h2 { display: flex; align-items: center; gap: 8px; }\n.borrar-resumen { margin: 0 0 8px; padding-left: 20px; }\nbutton.peligro { background: var(--aviso); color: var(--sobre-color); display: inline-flex; align-items: center; gap: 6px; }\nbutton.secundario.peligro { background: transparent; color: var(--aviso); border-color: var(--aviso); }\n.borrado-progreso { display: flex; flex-direction: column; gap: 4px; margin: 10px 0; color: var(--suave); }\n.borrado-progreso progress { width: 100%; height: 10px; }\n\n/* --- v0.29.0: ficha del asiento (rastro contable) --- */\n.ficha-cabecera { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }\n.ficha-cabecera h2 { margin: 0; }\n.ficha-datos { display: flex; flex-wrap: wrap; gap: 6px 24px; margin: 10px 0; }\n.ficha-datos dt { color: var(--suave); font-size: .85rem; }\n.ficha-datos dd { margin: 0; }\n.ficha-asiento.anulado table { opacity: .6; }\na.etiqueta { text-decoration: none; color: inherit; }\na.etiqueta:hover, a.etiqueta:focus-visible { text-decoration: underline; }\ntd a.enlace { color: inherit; }\ntd a.enlace .codigo, a.num-asiento { color: var(--primario); }\ntd a.enlace:hover .codigo, td a.enlace:focus-visible .codigo, a.num-asiento:hover { text-decoration: underline; }\na.num-asiento { font-variant-numeric: tabular-nums; }\n\n/* --- v0.30.0: indicadores del Inicio y gráfico de tesorería --- */\n.inicio-cabecera { grid-column: 1 / -1; }\n/* Las tarjetas de indicadores se reparten según el ancho de SU columna (arriba a todo el ancho o debajo de la ruta) */\n.inicio-cabecera, .inicio-principal { container-type: inline-size; }\n.kpis { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin: 0 0 16px; }\n.kpis > li { display: block; padding: 0; border: 0; }\n.kpis > li:first-child { grid-column: 1 / -1; }\n@container (min-width: 760px) {\n  .kpis { grid-template-columns: repeat(6, minmax(0, 1fr)); }\n  .kpis > li, .kpis > li:first-child { grid-column: span 2; }\n  .kpis > li:nth-child(n+4) { grid-column: span 3; }\n}\n.kpi { height: 100%; background: var(--tarjeta); border: 1px solid var(--borde); border-radius: 12px; padding: 14px 16px;\n       display: flex; flex-direction: column; gap: 4px; text-decoration: none; color: inherit; }\n.kpi:hover, .kpi:focus-visible { border-color: var(--primario); }\n.kpi-titulo { display: flex; align-items: center; gap: 6px; color: var(--suave); font-size: .85rem; }\n.kpi-titulo .icono-svg { color: var(--primario); }\n.kpi-valor { color: var(--texto); white-space: nowrap; font-size: 1.45rem; font-weight: 650; font-variant-numeric: tabular-nums; letter-spacing: -.01em; }\n.kpi-detalle { color: var(--suave); font-size: .82rem; }\n.kpi-detalle span { font-size: inherit; }   /* el \"li span\" general no se aplica dentro de las tarjetas */\n.kpi-detalle .sube { color: var(--exito); }\n.kpi-detalle .baja { color: var(--aviso); }\n.kpi-pie { color: var(--primario); font-size: .82rem; margin-top: auto; padding-top: 2px; }\n.grafico-cabecera { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; flex-wrap: wrap; }\n.grafico-cabecera h2 { margin: 0; }\n.grafico { position: relative; width: 100%; }\n.grafico svg { display: block; max-width: 100%; height: auto; overflow: visible; }\n.grafico .rejilla line { stroke: var(--borde); stroke-width: 1; }\n.grafico .eje text { fill: var(--suave); font-size: 11px; font-variant-numeric: tabular-nums; }\n.grafico .linea { fill: none; stroke: var(--primario); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }\n.grafico .area { fill: var(--primario); opacity: .10; }\n.grafico .punto { fill: var(--primario); stroke: var(--tarjeta); stroke-width: 2; }\n.grafico .cruz { stroke: var(--suave); stroke-dasharray: 3 3; }\n.grafico .valor-final { fill: var(--texto); font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; }\n.grafico .tooltip { position: absolute; pointer-events: none; background: var(--tarjeta); border: 1px solid var(--borde);\n                    border-radius: 8px; padding: 6px 10px; font-size: .85rem; box-shadow: 0 4px 14px rgba(0,0,0,.12); white-space: nowrap; }\n.grafico .tooltip strong { font-variant-numeric: tabular-nums; }\n.grafico-tesoreria .ayuda { margin: 0; }\n/* Uso de la web (v0.31.0): 4 cifras y las barras de visitantes por día */\n.uso-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px; margin: 8px 0 14px; padding: 0; }\n.uso-kpis > li { display: flex; flex-direction: column; gap: 2px; padding: 12px 14px; border: 1px solid var(--borde); }\n.uso-kpis .kpi-valor { font-size: 1.3rem; }\n.uso-kpis .kpi:hover { border-color: var(--borde); }   /* no es un enlace */\n.uso-web h3 { margin: 4px 0 6px; font-size: .95rem; }\n.grafico .barra { fill: var(--primario); }\n.grafico .barra.activa { opacity: .75; }\n.ruta-plegada summary { cursor: pointer; font-weight: 600; color: var(--exito); }\n.ruta-plegada[open] summary { margin-bottom: 8px; }\n\n/* --- v0.30.0: Balance y PyG comparativos (análisis horizontal) --- */\n.estado th small { display: block; font-weight: 400; color: var(--suave); font-size: .75rem; }\n.estado td.variacion { color: var(--suave); font-variant-numeric: tabular-nums; }\n.estado td.num { font-variant-numeric: tabular-nums; white-space: nowrap; }\n\n/* --- v0.30.0: cascada del EFE y evolución de los ratios --- */\n.figura-cascada { margin: 4px 0 8px; }\n.figura-cascada figcaption { font-weight: 600; margin-bottom: 4px; }\n.cascada { width: 100%; }\n.cascada svg { display: block; max-width: 100%; height: auto; overflow: visible; }\n.cascada .cero { stroke: var(--suave); stroke-width: 1; }\n.cascada .conector { stroke: var(--suave); stroke-dasharray: 3 3; }\n.cascada .tramo.total rect { fill: var(--primario); }\n.cascada .tramo.up rect { fill: var(--exito); }\n.cascada .tramo.down rect { fill: var(--aviso); }\n.cascada .valor { fill: var(--texto); font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; }\n.cascada .etiqueta { fill: var(--suave); font-size: 11px; }\n.tendencia-ratio svg { display: block; width: 100%; max-width: 420px; height: auto; overflow: visible; }\n.tendencia-ratio .zona { fill: var(--exito); opacity: .12; }\n.tendencia-ratio .linea { fill: none; stroke: var(--primario); stroke-width: 2; stroke-linejoin: round; }\n.tendencia-ratio .punto { fill: var(--primario); stroke: var(--tarjeta); stroke-width: 1.5; }\n.tendencia-ratio .anio { fill: var(--suave); font-size: 10px; }\n.tendencia-ratio .valor { fill: var(--texto); font-size: 10px; font-weight: 600; font-variant-numeric: tabular-nums; }\n\n/* --- v0.30.0: exportar a Excel e imprimir --- */\n.titulo-informe { display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; }\n.titulo-informe h2 { margin: 0; }\n.acciones-informe { display: flex; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }\n.acciones-informe button { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; font-size: .9rem; }\n.solo-impresion { display: none; }\n@media print {\n  /* La hoja impresa: solo el informe, en blanco y negro, sin menús ni botones (también desde el modo oscuro) */\n  :root { --fondo: #fff; --tarjeta: #fff; --texto: #000; --suave: #333; --borde: #bbb; --primario: #000; }\n  body, main { background: #fff !important; color: #000; }\n  main, main:has(.empresa-layout) { max-width: none; padding: 0; }\n  .cabecera, .empresa-cabecera, .menu-empresa, .boton-menu, .ruta, .acciones-informe, .rejilla-tres, .pestanas,\n  .leyenda-ratios, button:not(.ratio-fila), .busy, .aviso-modo, .ia-analista, .desplegar { display: none !important; }\n  .empresa-layout { display: block; }\n  .tarjeta { border: 0; padding: 0; margin: 0 0 12px; box-shadow: none; }\n  .solo-impresion { display: block; margin: 0 0 8px; font-size: .85rem; color: #333; }\n  .tabla-ancha, .tabla-scroll { overflow: visible !important; }\n  table { font-size: 9pt; }\n  tr, .asiento { break-inside: avoid; }\n  thead { display: table-header-group; }   /* la cabecera de la tabla se repite en cada página */\n  a { color: #000; text-decoration: none; }\n  svg .area { opacity: .15; }\n}\n\n/* --- v0.30.0: pulido · números alineados, filtros y tablas en el móvil --- */\nbody { line-height: 1.45; }\nh2 { letter-spacing: -.01em; }\n/* Todas las cifras con dígitos del mismo ancho: las columnas de importes se leen de un vistazo */\ntd.num, th.num, .num, .kpi-valor, .ultimos strong { font-variant-numeric: tabular-nums; }\ntd.num { white-space: nowrap; }\n@media (max-width: 560px) {\n  /* Filtros: uno debajo de otro, cada uno a todo el ancho */\n  .rejilla-tres { grid-template-columns: minmax(0, 1fr); }\n  /* Sumas y saldos y libro mayor como TARJETAS: una por cuenta o por movimiento, cada importe con su nombre */\n  table.tarjetas-movil thead { display: none; }\n  table.tarjetas-movil, table.tarjetas-movil tbody { display: block; }\n  table.tarjetas-movil tr { display: grid; grid-template-columns: auto 1fr; gap: 2px 10px; padding: 8px 0;\n                            border-bottom: 1px solid var(--borde); }\n  table.tarjetas-movil td { display: block; padding: 0; border: 0; }\n  table.tarjetas-movil td.celda-titulo { grid-column: 1 / -1; font-weight: 500; }\n  table.tarjetas-movil td.celda-fecha { color: var(--suave); }\n  table.tarjetas-movil td.celda-asiento { text-align: right; }\n  table.tarjetas-movil td.num { grid-column: 1 / -1; display: flex; justify-content: space-between; gap: 12px; }\n  table.tarjetas-movil td.num:empty { display: none; }\n  table.tarjetas-movil td.num::before { content: attr(data-label); color: var(--suave); font-variant-numeric: normal; }\n  table.tarjetas-movil tr.total td { grid-column: 1 / -1; font-weight: 700; }\n}\n/* --- v0.32.0: Cobros y pagos --- */\n.pagos h3 { margin: 10px 0 6px; font-size: .95rem; }\n.partidas li { display: grid; grid-template-columns: 22px minmax(0, 1fr) auto 8.5em; gap: 4px 12px; align-items: center; }\n.partidas li.marcada { background: color-mix(in srgb, var(--primario) 7%, transparent); }\n.partidas input[type=checkbox] { width: 18px; height: 18px; margin: 0; }\n.partida-info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }\n.partida-info strong { display: flex; flex-direction: row; flex-wrap: wrap; gap: 6px; align-items: center; }\n.partida-info .insignia { flex: none; width: auto; }\n.partida-pendiente { color: var(--texto) !important; font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; }\n.pagos input.importe { width: 100%; text-align: right; padding: 6px 8px; font-variant-numeric: tabular-nums; }\n@media (max-width: 560px) {\n  .partidas li { grid-template-columns: 22px minmax(0, 1fr) auto; }\n  .partidas input.importe { grid-column: 2 / 4; }\n}\n.vencida { color: var(--aviso); font-weight: 600; }\n.vista-asiento { display: flex; flex-wrap: wrap; gap: 4px 16px; align-items: baseline; padding: 10px 12px; margin: 8px 0;\n                 border: 1px dashed var(--borde); border-radius: 8px; font-variant-numeric: tabular-nums; }\n.vista-asiento span { color: var(--texto); }\n.fila-botones { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 8px; }\n.vincular { border-top: 1px solid var(--borde); margin-top: 12px; padding-top: 4px; }\n.lista-radio li { padding: 6px 0; }\n.lista-radio .opcion { flex-wrap: wrap; }\n.anular-pago { display: flex; flex-direction: column; gap: 6px; margin-top: 6px; max-width: 420px; }\n.estado-factura { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; margin-top: 4px; font-size: .85rem; }\n.estado-factura.paid .insignia { background: var(--exito); color: var(--sobre-color); }\n.estado-factura .enlace { font-size: inherit; }\n.retencion-tercero input.dias, .dias-pago input { width: 6em; padding: 6px 8px; }\n.antiguedad td .enlace { font-size: inherit; text-align: left; }\n.antiguedad td.fuerte { font-weight: 600; color: var(--texto); }\n.antiguedad .descuadre { display: block; color: var(--aviso); font-size: .8rem; font-weight: 500; white-space: nowrap; }\n\n/* --- v0.33.0: cuentas controladas y Comprobaciones --- */\n.aviso-controlada { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; margin: 8px 0; padding: 10px 14px;\n                    border-radius: 8px; border: 1px solid var(--alerta-fondo); border-left-width: 4px;\n                    background: color-mix(in srgb, var(--alerta-fondo) 10%, var(--tarjeta)); }\n.aviso-controlada.estricto { border-color: var(--aviso); background: color-mix(in srgb, var(--aviso) 6%, var(--tarjeta)); }\n.aviso-controlada p { margin: 0; }\n.aviso-controlada-titulo { font-weight: 600; color: var(--alerta); }\n.aviso-controlada.estricto .aviso-controlada-titulo { color: var(--aviso); }\n.aviso-controlada a.boton { padding: 6px 12px; font-size: .9rem; }\n.campo-fecha { display: flex; flex-direction: column; gap: 4px; max-width: 14em; }\n.resumen-comprobaciones { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; }\n.insignia-estado { display: inline-flex; align-items: center; gap: 4px; font-size: .8rem; font-weight: 700; padding: 2px 10px;\n                   border-radius: 999px; white-space: nowrap; }\n.insignia-estado.ok { background: color-mix(in srgb, var(--exito) 7%, transparent); color: var(--exito); }\n.insignia-estado.info { background: color-mix(in srgb, var(--primario) 6%, transparent); color: var(--primario); }\n.insignia-estado.warning { background: color-mix(in srgb, var(--alerta-fondo) 10%, transparent); color: var(--alerta); }\n.insignia-estado.error { background: color-mix(in srgb, var(--aviso) 14%, transparent); color: var(--aviso); }\n.lista-comprobaciones { display: flex; flex-direction: column; gap: 10px; margin-bottom: 16px; }\n.lista-comprobaciones li.comprobacion { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; padding: 12px 14px;\n                                        background: var(--tarjeta); border: 1px solid var(--borde); border-left: 4px solid var(--borde); border-radius: 10px; }\n.comprobacion.ok { border-left-color: var(--exito) !important; }\n.comprobacion.info { border-left-color: var(--primario) !important; }\n.comprobacion.warning { border-left-color: var(--alerta-fondo) !important; }\n.comprobacion.error { border-left-color: var(--aviso) !important; }\n.comprobacion p { margin: 0; color: var(--texto); font-size: .95rem; }\n.comprobacion p.ayuda { color: var(--suave); font-size: .9rem; }\n.comprobacion-cabecera { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; }\n.comprobacion-cabecera .insignia-estado { padding: 2px 8px; }\n.comprobacion .boton { padding: 6px 12px; font-size: .9rem; }\n.cifras-comprobacion { display: flex; flex-wrap: wrap; gap: 8px 24px; margin: 0; font-variant-numeric: tabular-nums; }\n.cifras-comprobacion div { display: flex; flex-direction: column; }\n.cifras-comprobacion dt { color: var(--suave); font-size: .8rem; }\n.cifras-comprobacion dd { margin: 0; font-weight: 600; }\n.cifras-comprobacion .diferencia dd { color: var(--aviso); }\n.comprobacion-detalle { width: 100%; font-size: .9rem; }\n.comprobacion-detalle summary { cursor: pointer; color: var(--primario); }\n.comprobacion-detalle table { width: 100%; border-collapse: collapse; margin-top: 6px; font-variant-numeric: tabular-nums; }\n.comprobacion-detalle th, .comprobacion-detalle td { text-align: left; padding: 4px 8px; border-bottom: 1px solid var(--borde); white-space: nowrap; }\n.comprobacion-detalle th { color: var(--suave); font-weight: 600; font-size: .8rem; }\n.comprobacion-arreglo { color: var(--suave) !important; }\n.opciones-modo { display: grid; gap: 8px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr)); }   /* v0.41.1: en dos columnas si caben */\n.opcion-modo { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border: 1px solid var(--borde); border-radius: 8px; cursor: pointer; }\n.opcion-modo.activa { border-color: var(--primario); background: color-mix(in srgb, var(--primario) 6%, var(--tarjeta)); }\n.opcion-modo input { margin-top: 3px; }\n.opcion-modo span { display: flex; flex-direction: column; gap: 2px; }\n.opcion-modo small { color: var(--suave); }\n\n/* --- v0.35.0: Inmovilizado --- */\n.fila-amortizar { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 10px; }\n.fila-amortizar label { max-width: 14em; }\n.lista-activos li { display: flex; flex-direction: column; align-items: flex-start; gap: 4px; padding: 10px 6px; }\n.lista-activos li.marcada { background: color-mix(in srgb, var(--primario) 7%, transparent); }\n.lista-activos button.enlace { padding: 0; text-align: left; color: var(--primario); }\n.importes-activo { display: flex; flex-wrap: wrap; gap: 4px 18px; font-variant-numeric: tabular-nums; }\n.importes-activo strong { color: var(--texto); }\n.ficha-activo h3, .baja-activo h3 { margin: 6px 0 2px; font-size: .95rem; }\n.ficha-activo td.num, .ficha-activo th.num { text-align: right; font-variant-numeric: tabular-nums; }\n.baja-activo { display: flex; flex-direction: column; gap: 10px; border-top: 1px solid var(--borde); padding-top: 10px; }\n.baja-activo label { max-width: 28em; }\n.alta-activo .rejilla-tres label { min-width: 0; }\n@media (max-width: 560px) { .alta-activo .rejilla-tres { grid-template-columns: 1fr 1fr; } }\n\n/* --- v0.36.0: Ajustes de cierre --- */\n.ajustes .campo-fecha { max-width: 14em; }\n.ajustes ~ .tarjeta td.num, .ajustes ~ .tarjeta th.num { text-align: right; font-variant-numeric: tabular-nums; }\n.ajustes ~ .tarjeta td small { color: var(--suave); }\n.ajustes ~ .tarjeta tr.anulada td { color: var(--suave); text-decoration: line-through; }\n.ajustes ~ .tarjeta tr.marcada td { background: color-mix(in srgb, var(--primario) 7%, transparent); }\n.ajustes ~ .tarjeta td.acciones { white-space: nowrap; }\n.ajustes ~ .tarjeta td.acciones button { padding: 6px 10px; font-size: .85rem; margin: 2px 4px 2px 0; }\n.ajustes ~ .tarjeta td input { max-width: 5em; text-align: right; }\n.accion-deterioro { display: flex; flex-direction: column; align-items: flex-start; gap: 4px; white-space: normal; min-width: 14em; }\n.accion-deterioro label { display: flex; align-items: center; gap: 6px; }\n.ajustes ~ .tarjeta td:first-child { white-space: nowrap; }\n\n/* --- v0.37.0: provisiones, existencias, deterioro del inmovilizado y asistente de cierre --- */\n.movimientos-provision { display: flex; flex-direction: column; gap: 2px; font-size: .85rem; color: var(--suave); font-variant-numeric: tabular-nums; }\n.acciones-provision { display: flex; flex-wrap: wrap; gap: 6px; }\n.acciones-provision button { padding: 6px 10px; font-size: .85rem; }\n.sucesos-activo { margin: 4px 0 0; padding-left: 1.2em; font-size: .9rem; font-variant-numeric: tabular-nums; }\n.pasos-cierre { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }\n.paso-cierre { display: grid; grid-template-columns: auto 1fr auto; gap: 4px 10px; align-items: start; padding: 8px 10px;\n  border: 1px solid var(--borde); border-radius: 8px; border-left: 4px solid var(--borde); }\n.paso-cierre.done { border-left-color: var(--exito, #2e7d32); }\n.paso-cierre.pending { border-left-color: var(--alerta-fondo); }\n.paso-cierre.review { border-left-color: var(--primario); }\n.paso-cierre.na { opacity: .7; }\n.paso-cierre .paso-texto { display: flex; flex-direction: column; gap: 2px; }\n.paso-cierre .paso-texto small { color: var(--suave); }\n.paso-cierre .enlace { white-space: nowrap; font-size: .9rem; }\n.insignia-estado.na { background: var(--fondo); color: var(--suave); }\n@media (max-width: 560px) { .paso-cierre { grid-template-columns: auto 1fr; } .paso-cierre .enlace { grid-column: 2; } }\n\n/* --- v0.38.0: Nóminas --- */\n.nominas .campo-fecha { max-width: 14em; }\n:is(.nominas, .nominas ~ .tarjeta) :is(td.num, th.num) { text-align: right; font-variant-numeric: tabular-nums; }\n:is(.nominas, .nominas ~ .tarjeta) td small { color: var(--suave); }\n:is(.nominas, .nominas ~ .tarjeta) td:first-child { white-space: nowrap; }\n.nominas ~ .tarjeta tr.anulada td { color: var(--suave); text-decoration: line-through; }\n.nominas ~ .tarjeta tr.marcada td { background: color-mix(in srgb, var(--primario) 7%, transparent); }\n.nominas ~ .tarjeta td.acciones { white-space: nowrap; }\n.nominas ~ .tarjeta td.acciones button { padding: 6px 10px; font-size: .85rem; margin: 2px 4px 2px 0; }\n.nominas ~ .tarjeta td .enlace { padding: 0; font-weight: 600; color: var(--primario); }\n.recibos { display: grid; grid-template-columns: repeat(auto-fill, minmax(17em, 1fr)); gap: 10px; white-space: normal; }\n.recibo { border: 1px solid var(--borde); border-radius: 8px; padding: 10px 12px; display: flex; flex-direction: column; gap: 6px; }\n.recibo h4 { margin: 0; font-size: .95rem; }\n.recibo dl { margin: 0; display: grid; gap: 2px; font-variant-numeric: tabular-nums; }\n.recibo dl div { display: flex; justify-content: space-between; gap: 10px; }\n.recibo dt { font-weight: 400; }\n.recibo dt small { color: var(--suave); }\n.recibo dd { margin: 0; text-align: right; white-space: nowrap; }\n.recibo dl div.total { border-top: 1px solid var(--borde); padding-top: 4px; }\n.recibo details summary { cursor: pointer; font-size: .9rem; }\n.recibo > small { color: var(--suave); }\n\n/* --- v0.39.0: Modelos y fuentes oficiales --- */\n.pestanas { display: flex; flex-wrap: wrap; gap: 6px; margin: 4px 0 12px; }\n.pestanas button { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; padding: 8px 14px; font-weight: 700;\n  background: var(--fondo); color: var(--texto); border: 1px solid var(--borde); border-radius: 8px; }\n.pestanas button small { font-weight: 400; color: var(--suave); }\n.pestanas button.activa { background: var(--tarjeta); color: var(--texto); border-color: var(--primario); box-shadow: inset 0 -3px 0 var(--primario); }\n.titulo-modelo { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; }\n.titulo-modelo h2 { margin: 0; }\ntable.casillas caption { text-align: left; font-weight: 700; padding: 10px 0 4px; }\ntable.casillas td.casilla { font-variant-numeric: tabular-nums; font-weight: 700; white-space: nowrap; width: 4.5em; }\ntable.casillas :is(td.num, th.num) { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }\ntable.casillas tr.total td { font-weight: 700; border-top: 1px solid var(--borde); }\n.resultado-modelo { font-weight: 700; padding: 8px 12px; border-radius: 8px; border-left: 4px solid var(--borde); }\n.resultado-modelo.pay { border-left-color: var(--alerta-fondo); }\n.resultado-modelo.credit { border-left-color: var(--primario); }\n.aviso-periodo.monthly { font-weight: 700; }\n.fuentes { position: relative; display: inline-block; font-size: .9rem; font-weight: 400; }\n.fuentes-boton { padding: 4px 10px; font-size: .85rem; background: var(--fondo); color: var(--primario); border: 1px solid var(--borde); border-radius: 999px; }\n.fuentes-panel { position: absolute; z-index: 30; top: calc(100% + 6px); left: 0; width: min(26rem, 86vw); display: flex; flex-direction: column; gap: 6px;\n  padding: 12px; background: var(--tarjeta, #fff); color: var(--texto); border: 1px solid var(--borde); border-radius: 10px; box-shadow: 0 8px 24px rgba(0,0,0,.18); }\n.fuentes-panel ul { margin: 0; padding-left: 1.1em; display: flex; flex-direction: column; gap: 8px; }\n.fuentes-panel li { display: flex; flex-direction: column; gap: 2px; }\n.fuentes-panel small { color: var(--suave); }\n.fuentes-panel .fuente-revisar { color: var(--alerta); font-weight: 600; }\n\n/* --- v0.40.0: Practicar (supuestos autocorregidos) y «dónde se registra» del Tutor --- */\n.practicar .fila-glosario { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }\n.practicar .fila-glosario h2 { margin: 0; display: inline-flex; align-items: center; gap: 6px; }\n.progreso-practica { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 4px 0 8px; }\n.progreso-practica progress { width: min(240px, 100%); height: 10px; accent-color: var(--exito); }\n.nivel-practica h3 { margin: 16px 0 6px; font-size: 1rem; }\n.lista-supuestos { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }\n.lista-supuestos a { display: grid; grid-template-columns: 1.6em 1fr auto; align-items: center; gap: 2px 8px; padding: 8px 12px;\n  border: 1px solid var(--borde); border-radius: 8px; color: var(--texto); text-decoration: none; }\n.lista-supuestos a:hover { border-color: var(--primario); }\n.lista-supuestos small { grid-column: 2 / -1; color: var(--suave); }\n.lista-supuestos .estado-supuesto { font-weight: 700; color: var(--suave); }\n.lista-supuestos li.solved .estado-supuesto { color: var(--exito); }\n.lista-supuestos li.tried .estado-supuesto { color: var(--alerta); }\n.titulo-supuesto { font-weight: 600; }\n.supuesto .titulo-modelo h3 { margin: 0; }\n.enunciado { font-size: 1.02rem; line-height: 1.5; padding: 10px 12px; border-left: 4px solid var(--primario); background: var(--fondo); border-radius: 6px; }\n.lineas-respuesta { display: flex; flex-direction: column; gap: 6px; margin: 8px 0; }\n.linea-respuesta { display: grid; grid-template-columns: minmax(5.5em, 1fr) minmax(6em, 1.2fr) minmax(6em, 1.2fr) 2.6em; gap: 6px; align-items: center; }\n.linea-respuesta input { min-width: 0; font-variant-numeric: tabular-nums; }\n.linea-respuesta input[inputmode=\"decimal\"], .linea-respuesta .num { text-align: right; }\n.cabecera-respuesta { font-size: .8rem; font-weight: 700; color: var(--suave); }\n.total-respuesta { border-top: 1px solid var(--borde); padding-top: 6px; font-variant-numeric: tabular-nums; }\n.correccion { margin: 12px 0; padding: 10px 12px; border-radius: 8px; border-left: 4px solid var(--alerta-fondo); background: var(--fondo); }\n.correccion.bien { border-left-color: var(--exito); }\n.nota-supuesto { margin: 0 0 6px; }\n.correccion .bloque-ia h4, .solucion-supuesto h4 { margin: 8px 0 4px; }\n.solucion-supuesto { margin-top: 8px; padding-top: 4px; border-top: 1px solid var(--borde); }\n.donde-registra { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 6px; }\n.donde-registra small { flex-basis: 100%; color: var(--suave); }\n@media (max-width: 480px) { .linea-respuesta { grid-template-columns: 5.8em 1fr 1fr 2.4em; gap: 4px; } }\n.supuesto .fila { flex-wrap: wrap; align-items: center; }\n.practicar .etiqueta { color: var(--texto); background: color-mix(in srgb, var(--primario) 12%, transparent); }\n.lista-supuestos li { border: 0; padding: 0; margin: 0; }\n.lista-supuestos .titulo-supuesto { color: var(--texto); font-size: 1rem; }\n.evaluar-ia { margin-top: 20px; padding-top: 12px; border-top: 1px solid var(--borde); }\n.evaluar-ia h3 { margin: 0 0 4px; font-size: 1rem; }\n.fila-evaluar { flex-wrap: wrap; align-items: flex-end; }\n.fila-evaluar label { flex: 1 1 16rem; }\n.resumen-ia-evaluacion { font-weight: 600; }\n.evaluar-ia td.num { white-space: nowrap; }\n.cuadre-respuesta { margin: 0; min-height: 1.2em; text-align: right; color: var(--aviso); }\n\n/* --- v0.41.0: Impuesto sobre Sociedades --- */\n.etiqueta.etiqueta-texto { color: var(--texto); background: color-mix(in srgb, var(--primario) 12%, transparent); }\n.estado-is { font-weight: 600; padding: 6px 10px; border-radius: 6px; border-left: 4px solid var(--borde); background: var(--fondo); }\n.estado-is.draft { border-left-color: var(--alerta-fondo); }\n.estado-is.posted { border-left-color: var(--exito); }\ntable.casillas tr.excluido td { color: var(--suave); text-decoration: line-through; }\ntable.casillas tr.excluido td:first-child { text-decoration: none; }\n.articulo { color: var(--suave); }\n.ajuste-manual { display: flex; flex-direction: column; gap: 8px; margin-top: 8px; padding: 10px; border: 1px dashed var(--borde); border-radius: 8px; }\n.ajuste-manual .fila { flex-wrap: wrap; }\n.impuesto-sociedades + .tarjeta label.opcion { display: flex; gap: 8px; align-items: flex-start; }\n\n/* --- v0.41.2 · PANEL DE IA: botón flotante abajo a la derecha y panel lateral (en el móvil, a pantalla completa) --- */\n.boton-ia { position: fixed; right: 20px; bottom: 20px; z-index: 60; border-radius: 999px; padding: 12px 18px;\n            font-weight: 700; box-shadow: 0 6px 20px rgba(0,0,0,.25); display: flex; align-items: center; gap: 6px; }\n.boton-ia[aria-expanded=\"true\"] { background: var(--texto); color: var(--fondo); }\n.panel-ia { position: fixed; z-index: 55; top: 0; right: 0; bottom: 0; width: min(440px, 100vw); display: flex; flex-direction: column;\n            background: var(--tarjeta); border-left: 1px solid var(--borde); box-shadow: -8px 0 24px rgba(0,0,0,.15); }\n.panel-ia[hidden] { display: none; }\n.panel-ia-cabecera { display: flex; align-items: center; justify-content: space-between; padding: 12px 14px; border-bottom: 1px solid var(--borde); }\n.panel-ia-cabecera .cerrar { padding: 4px 10px; }\n.panel-ia-pestanas { display: flex; gap: 4px; padding: 8px 14px 0; border-bottom: 1px solid var(--borde); }\n.panel-ia-pestanas button { background: transparent; color: var(--suave); border-radius: 8px 8px 0 0; border-bottom: 2px solid transparent; }\n.panel-ia-pestanas button.activa { color: var(--primario); border-bottom-color: var(--primario); font-weight: 700; }\n.panel-ia-contenido { flex: 1; overflow-y: auto; padding: 12px 14px 0; }\n.chat-ia { display: flex; flex-direction: column; gap: 10px; }\n.chat-mensajes { display: flex; flex-direction: column; gap: 14px; }\n.chat-mensajes > li { border: 0; padding: 0; }\n.chat-turno { display: flex; flex-direction: column; gap: 6px; }\n.burbuja { margin: 0; padding: 10px 12px; border-radius: 12px; line-height: 1.45; }\n.burbuja.usuario { align-self: flex-end; max-width: 85%; background: var(--primario); color: var(--sobre-color); border-bottom-right-radius: 4px; white-space: pre-wrap; }\n.burbuja.ia { background: var(--fondo); border: 1px solid var(--borde); border-bottom-left-radius: 4px; display: flex; flex-direction: column; gap: 8px; }\n.burbuja.escribiendo { color: var(--suave); }\n.burbuja .propuesta { display: flex; flex-direction: column; gap: 8px; }\n.burbuja table .porque { display: block; color: var(--suave); font-size: .8rem; }\n.chat-entrada { position: sticky; bottom: 0; z-index: 2; display: flex; flex-direction: column; gap: 6px; background: var(--tarjeta);\n               padding: 8px 0; box-shadow: 0 -10px 12px -6px var(--tarjeta); }\n.chat-entrada textarea { width: 100%; resize: vertical; font: inherit; padding: 8px 10px; border-radius: 8px; border: 1px solid var(--borde);\n                         background: var(--tarjeta); color: var(--texto); }\n.chat-entrada button { align-self: flex-end; }\n.en-panel h3 { margin: 0; }\n.analista-ia.en-panel { border-left: 0; }\n.pedir-ia { margin: 0 0 12px; }\n@media (min-width: 1100px) {\n  /* PC ancho: el panel se pone al lado y el contenido deja su sitio (no tapa nada) */\n  .empresa-layout:has(> .panel-ia:not([hidden])) { padding-right: 440px; }\n  .boton-ia[aria-expanded=\"true\"] { right: 460px; }\n}\n@media (max-width: 600px) {\n  .boton-ia { right: 12px; bottom: 12px; padding: 10px 14px; }\n  .boton-ia[aria-expanded=\"true\"] { display: none; }   /* a pantalla completa se cierra con ✕ o Escape */\n}\n@media print { .boton-ia, .panel-ia { display: none !important; } }\n\n/* --- v0.41.1 · DENSIDAD EN EL PC: letra un poco más pequeña y menos relleno, para que quepa más sin hacer scroll ---\n   Solo en pantalla y desde 900 px (el móvil y la impresión no cambian). Los tamaños en rem bajan solos con la raíz\n   (16 → 14 px); los rellenos en px se ajustan aquí. Quien la quiera más grande puede usar el zoom del navegador. */\n@media screen and (min-width: 900px) {\n  html { font-size: 14px; }\n  :root { line-height: 1.4; }\n  main:has(.empresa-layout) { padding: 12px 20px; }\n  .tarjeta { padding: 12px 14px; margin-bottom: 12px; gap: 8px; }\n  .empresa-contenido { gap: 0 12px; }\n  input, select, button { padding: 6px 10px; }\n  li { padding: 6px 0; }\n  h2 { margin-bottom: 8px; }\n  .tarjeta h3 { margin: 6px 0 2px; }\n  .tarjeta > h3:first-child, .tarjeta > h2:first-child { margin-top: 0; }\n  .menu-empresa { padding: 6px; gap: 6px; }\n  .menu-grupo button { padding: 5px 8px; }\n}\n\n/* v0.43.0 · Financiación: en el cuadro, las cuotas pagadas en gris y la siguiente resaltada */\ntable.informe tr.excluido td { color: var(--suave); }\ntable.informe tr.seleccionado td { background: color-mix(in srgb, var(--primario) 9%, transparent); }\n.tarjeta details summary { cursor: pointer; }\n\n/* v0.44.0 · Subvenciones: las casillas, en su propia fila (casilla y texto juntos) */\n.opciones-subvencion { display: flex; flex-wrap: wrap; gap: .5rem 1.5rem; margin: .5rem 0; }\n.opciones-subvencion label.opcion { display: flex; align-items: center; gap: .4rem; }\n.opciones-subvencion label.opcion input { width: auto; margin: 0; }\n\n/* v0.46.0 · Casos completos */\n.caso-cargar { border-top: 1px solid var(--borde); padding-top: 10px; margin-top: 10px; }\n.caso-cargar > p { margin: 4px 0; }\n.grupo-caso { border-top: 1px solid var(--borde); padding: 6px 0; }\n.grupo-caso > summary { cursor: pointer; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; padding: 4px 0; }\n.grupo-caso table .codigo { min-width: 4.5em; display: inline-block; }\n.asientos-caso .enlace { white-space: nowrap; }\n\n/* v0.47.0 · Fecha rápida y contabilidad mes a mes */\n.campo-fecha { display: flex; flex-direction: column; gap: 2px; position: relative; }\n.fila-fecha { display: flex; align-items: center; gap: 4px; }\n.fila-fecha input[type=\"text\"] { flex: 1; min-width: 8.5em; }\n.boton-calendario { flex: none; padding: 4px 8px; background: transparent; border: 1px solid var(--borde); color: var(--texto); }\n.selector-oculto { position: absolute; right: 0; bottom: 0; width: 1px; height: 1px; opacity: 0; pointer-events: none; border: 0; padding: 0; }\n.barra-mes { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; position: relative; }\n.mes-abierto { white-space: nowrap; padding: 4px 10px; border-radius: 999px; background: color-mix(in srgb, var(--primario) 8%, var(--tarjeta)); }\n.empresa-cabecera .barra-mes { flex-direction: row; }\n.empresa-cabecera .panel-mes, .empresa-cabecera .panel-mes span { color: var(--texto); font-size: inherit; }\n.empresa-cabecera .panel-mes .fila-botones { flex-direction: row; }\n.barra-mes > button { padding: 6px 12px; font-size: .9rem; }\n.campo-fecha .aviso { font-size: .8rem; }\n.panel-mes { position: absolute; top: calc(100% + 6px); left: 0; z-index: 20; width: min(440px, 92vw); padding: 14px 16px;\n  background: var(--tarjeta); border: 1px solid var(--borde); border-radius: 10px; box-shadow: 0 8px 24px rgba(0,0,0,.15); }\n.panel-mes h3 { margin: 0 0 8px; }\n.avisos-mes { padding-left: 0; list-style: none; display: flex; flex-direction: column; gap: 6px; margin: 8px 0; }\n@media (max-width: 700px) { .panel-mes { position: fixed; left: 4vw; right: 4vw; top: 70px; width: auto; } }\n\n/* v0.47.0 · Pantalla «Asientos»: color de la fila muy suave según el estado (el texto del estado lo dice también) */\n:root { --fila-posted: color-mix(in srgb, var(--exito) 7%, var(--tarjeta)); --fila-ok: color-mix(in srgb, var(--suave) 9%, var(--tarjeta));\n  --fila-error: color-mix(in srgb, var(--aviso) 8%, var(--tarjeta)); }\n.botones-rango { display: flex; flex-wrap: wrap; gap: 6px; margin: 6px 0 10px; }\n.botones-rango button { padding: 6px 14px; border-radius: 999px; font-size: .9rem; }\n.botones-rango button.activo { background: var(--primario); color: var(--sobre-color); border: 1px solid var(--primario); }\n.lista-asientos tbody tr.fila-asiento { cursor: pointer; }\n.lista-asientos tbody tr.estado-posted td { background: var(--fila-posted); }\n.lista-asientos tbody tr.estado-ok td { background: var(--fila-ok); }\n.lista-asientos tbody tr.estado-error td { background: var(--fila-error); }\n.lista-asientos tbody tr.fila-asiento:hover td { filter: brightness(.97); }\n.lista-asientos .enlace-fila { color: inherit; text-decoration: none; }\n.lista-asientos .enlace-fila:hover, .lista-asientos .enlace-fila:focus-visible { text-decoration: underline; }\n.texto-estado { white-space: nowrap; font-weight: 600; font-size: .85rem; }\n.texto-estado.estado-posted { color: var(--exito); }\n.texto-estado.estado-ok { color: var(--suave); }\n.texto-estado.estado-error { color: var(--aviso); }\n.lista-asientos .motivo { display: block; color: var(--aviso); font-size: .78rem; }\n.insignia-estado.estado-posted { background: var(--fila-posted); color: var(--exito); }\n.insignia-estado.estado-ok { background: var(--fila-ok); color: var(--texto); }\n.insignia-estado.estado-error { background: var(--fila-error); color: var(--aviso); }\n.papelera.visible { opacity: 1; }\na.boton-enlace { display: inline-block; padding: 6px 14px; border-radius: 8px; background: var(--primario); color: var(--sobre-color); text-decoration: none; }\n.lista-asientos thead th { position: relative; }   /* el texto oculto de las cabeceras no se sale de la tabla en el móvil */\n.lista-asientos { width: 100%; }\n.lista-asientos th:first-child, .lista-asientos td:first-child { width: 2.2em; min-width: 0; padding-right: 0; }\n.lista-asientos th:last-child, .lista-asientos td:last-child { width: 2.6em; padding-left: 0; }\n.lista-asientos td:nth-child(5) { min-width: 14em; }\n\n/* v0.47.0 · Crear una subcuenta sin salir del asiento */\n.linea .cuenta-rapida { grid-column: 1 / -1; display: flex; flex-direction: column; gap: 6px; margin: 4px 0 10px; padding: 10px 12px;\n  border: 1px solid var(--primario); border-radius: 8px; background: color-mix(in srgb, var(--primario) 5%, var(--tarjeta)); }\n\n/* v0.48.0 · PGC de estudio (#/pgc): árbol de cuentas a la izquierda, ficha a la derecha. Debe en azul y Haber en teja */\n:root { --debe: #1f5f8b; --haber: #9a4a1c; }\n@media (prefers-color-scheme: dark) { :root { --debe: #7fb6dd; --haber: #e3a07a; } }\nmain:has(.pgc) { max-width: 1200px; }\n.pgc li, .pgc-ficha li, .panel-pgc li { display: block; padding: 0; border: 0; }   /* sin el estilo general de las listas (filas con raya) */\n.pgc li span, .pgc-ficha li span { color: inherit; font-size: inherit; }\n.pgc-lado ul, .pgc-donde { list-style: disc; }\n.pgc-lado li, .pgc-donde li { display: list-item; }\n.pgc .fila-glosario { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }\n.pgc .fila-glosario h2 { margin: 0; display: inline-flex; align-items: center; gap: 6px; }\n.pgc-pestanas { margin: 8px 0 14px; }\n.pgc-pestanas button { flex: 0 1 auto; padding: 8px 14px; }\n.pgc-rejilla { display: grid; grid-template-columns: 360px 1fr; gap: 16px; align-items: start; }\n.pgc-rejilla > * { min-width: 0; }\n.pgc-lateral { position: sticky; top: 12px; max-height: calc(100vh - 24px); display: flex; flex-direction: column; gap: 8px;\n  padding: 12px; border: 1px solid var(--borde); border-radius: 10px; background: var(--tarjeta); }\n.pgc-lateral .ayuda { margin: 0; }\n.pgc-chips { display: flex; flex-wrap: wrap; gap: 4px; }\n.pgc-chips button { padding: 3px 10px; border-radius: 999px; font-size: .8rem; background: transparent; color: var(--texto); border: 1px solid var(--borde); }\n.pgc-chips button.activo { background: var(--primario); color: var(--sobre-color); border-color: var(--primario); }\n.pgc-lista { position: relative; list-style: none; margin: 0; padding: 0; overflow: auto; flex: 1; min-height: 120px; }\n.pgc li.pgc-grupo { margin: 10px 0 2px; font-weight: 650; color: var(--primario); }\n.pgc li.pgc-grupo small { display: block; font-weight: 400; color: var(--suave); font-size: .78rem; }\n.pgc li.pgc-subgrupo { margin: 6px 0 2px; font-size: .72rem; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--suave); }\n.pgc-fila { display: flex; gap: 8px; align-items: baseline; width: 100%; text-align: left; padding: 4px 6px; border-radius: 6px;\n  background: transparent; color: var(--texto); border: 1px solid transparent; font-size: .9rem; }\n.pgc-fila:hover { background: color-mix(in srgb, var(--primario) 6%, transparent); }\n.pgc-fila[aria-current=\"true\"] { background: color-mix(in srgb, var(--primario) 12%, var(--tarjeta)); border-color: var(--primario); }\n:is(.pgc, .panel-pgc) .pgc-fila .pgc-mono { color: var(--suave); min-width: 38px; }\n.pgc-nombre { flex: 1; }\n:is(.pgc, .panel-pgc) .pgc-fila .pgc-marca { color: color-mix(in srgb, var(--primario) 75%, var(--texto)); font-size: .75rem; white-space: nowrap; }\n.pgc-mono { font-family: ui-monospace, \"SF Mono\", Consolas, monospace; font-variant-numeric: tabular-nums; }\n.pgc-derecha { padding: 4px 4px 12px; scroll-margin-top: 12px; }\n.pgc-ficha p { line-height: 1.55; }\n.pgc-codigo { margin: 0; color: var(--suave); font-family: ui-monospace, \"SF Mono\", Consolas, monospace; font-size: .9rem; }\n.pgc-titulo { margin: 2px 0 4px; font-size: 1.45rem; }\n.pgc-migas { margin: 0 0 10px; color: var(--suave); font-size: .85rem; }\n.pgc-pendiente { margin: 0 0 10px; padding: 6px 10px; border-radius: 8px; font-size: .85rem;\n  background: color-mix(in srgb, var(--alerta) 12%, var(--tarjeta)); color: var(--texto); border-left: 3px solid var(--alerta); }\n.pgc-uso { font-size: 1.02rem; }\n.pgc-lados { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.pgc-lado { border: 1px solid var(--borde); border-radius: 8px; padding: 10px 12px; }\n.pgc-lado h3 { margin: 0 0 6px; font-size: .95rem; }\n.pgc-lado ul { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 4px; line-height: 1.45; }\n.pgc-debe h3 { color: var(--debe); }\n.pgc-haber h3 { color: var(--haber); }\n.pgc-seccion { margin: 20px 0 6px; font-size: .75rem; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; color: var(--suave); }\n.pgc-donde { margin: 0; padding-left: 18px; line-height: 1.5; }\n.pgc-etiqueta { padding: 3px 10px; border-radius: 6px; font-size: .82rem; text-align: left;\n  background: color-mix(in srgb, var(--primario) 10%, transparent); color: var(--texto); border: 1px solid color-mix(in srgb, var(--primario) 30%, transparent); }\n.pgc-etiqueta:hover { border-color: var(--primario); }\n.pgc-tabla { overflow-x: auto; }\n.pgc-tabla table { min-width: 420px; width: 100%; border-collapse: collapse; font-size: .9rem; }\n.pgc-tabla th, .pgc-tabla td { padding: 5px 8px; border-bottom: 1px solid var(--borde); text-align: left; }\n.pgc-tabla .num { text-align: right; }\n.pgc-tabla tfoot th, .pgc-tabla tfoot td { font-weight: 700; border-bottom: 0; }\n.pgc-ojo { margin-top: 16px; padding: 10px 12px; border-radius: 8px; line-height: 1.5;\n  background: color-mix(in srgb, var(--alerta-fondo) 16%, var(--tarjeta)); color: var(--texto); }\n.pgc-terminos { display: flex; flex-wrap: wrap; gap: 4px 14px; }\nbutton.enlace.pgc-ir { display: inline; align-self: auto; font: inherit; text-decoration: underline; text-underline-offset: 2px; }\n.pgc-ojo button.enlace.pgc-ir { color: inherit; font-weight: 600; }\n.pgc-tarjetas { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.pgc .pgc-tarjeta { border: 1px solid var(--borde); border-radius: 10px; padding: 12px 14px; scroll-margin-top: 12px; outline: 2px solid transparent; }\n.pgc-tarjeta.resaltada { animation: pgc-resalte 1.6s ease-in forwards; }\n@keyframes pgc-resalte { 0%, 70% { outline-color: var(--primario); } 100% { outline-color: transparent; } }\n@media (prefers-reduced-motion: reduce) { .pgc-tarjeta.resaltada { animation: none; outline-color: var(--primario); } }\n.pgc-tarjeta h3 { margin: 2px 0 6px; font-size: 1.05rem; }\n.pgc-tarjeta p { margin: 0 0 8px; line-height: 1.5; }\n.pgc-num { color: var(--primario); font-size: .85rem; }\n@media (max-width: 800px) {\n  .pgc-rejilla { grid-template-columns: 1fr; }\n  .pgc-lateral { position: static; max-height: 60vh; }\n}\n@media (max-width: 560px) { .pgc-lados { grid-template-columns: 1fr; } }\n@media (max-width: 480px) { .cabecera { flex-wrap: wrap; } .cabecera-acciones { flex-wrap: wrap; } }   /* con «PGC» ya no caben en una fila */\n@media print { main:has(.pgc) { max-width: none; } .pgc-lateral, .pgc-pestanas { display: none; } .pgc-rejilla { display: block; } }\n\n/* v0.48.0 · El PGC en Nuevo asiento: botón en la cabecera, ⓘ en cada línea y panel lateral (como el de la IA) */\n.titulo-modelo .boton-pgc { display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; margin-left: auto; }\n.pgc-i { background: transparent; color: var(--primario); border: 0; padding: 0 4px 0 0; font-size: .95rem; line-height: 1; cursor: help; }\n.pgc-i:hover { color: var(--texto); }\n.panel-pgc { z-index: 57; }\n.panel-pgc .panel-ia-cabecera strong { display: inline-flex; align-items: center; gap: 6px; }\n.panel-pgc .panel-ia-contenido { padding-bottom: 16px; }\n.panel-pgc #pgc-panel-buscar { width: 100%; margin-bottom: 10px; }\n.panel-pgc .pgc-resultados { max-height: none; overflow: visible; }\n.panel-pgc .pgc-titulo { font-size: 1.25rem; }\n.panel-pgc .pgc-titulo:focus { outline: none; }\n.panel-pgc .pgc-titulo:focus-visible { outline: 2px solid var(--primario); border-radius: 4px; }\n.panel-pgc .pgc-lados { grid-template-columns: 1fr; }\n.panel-pgc .pgc-tabla table { min-width: 380px; font-size: .82rem; }\n.pgc-norma { margin-bottom: 14px; border: 1px solid var(--primario); border-radius: 10px; padding: 10px 12px; }\n.pgc-norma h3 { margin: 2px 0 6px; font-size: 1rem; }\n.pgc-norma p { margin: 0 0 8px; line-height: 1.5; }\n.pgc-completo { margin: 16px 0 0; }\n@media (min-width: 1100px) {\n  .empresa-layout:has(.panel-pgc:not([hidden])) { padding-right: 440px; }\n  body:has(.panel-pgc:not([hidden])) .boton-ia { right: 460px; }\n}\n@media (max-width: 1099px) { body:has(.panel-pgc:not([hidden])) .boton-ia { display: none; } }\n@media print { .panel-pgc, .boton-pgc, .pgc-i { display: none !important; } }\n.panel-pgc:focus { outline: none; }\n\n/* v0.49.0 · Empresas temporales de los registrados */\n.insignia.insignia-temporal { background: color-mix(in srgb, var(--alerta) 16%, var(--tarjeta)); color: var(--texto); }\n/* v0.59.0 · Empresas sintéticas con semilla */\n.insignia.insignia-sintetica { background: color-mix(in srgb, var(--primario) 14%, var(--tarjeta)); color: var(--texto); letter-spacing: 0; }\n.sintetica-cabecera { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; margin: 0 0 10px; grid-column: 1 / -1; }\n.sintetica-cabecera .insignia { font-size: .8rem; text-transform: none; }\n.sintetica .fila input { flex: 1; min-width: 0; }\n.sintetica .fila button { flex: 0 0 auto; width: auto; }\n.sintetica-informe { width: 100%; font-family: ui-monospace, monospace; font-size: .85rem; }\n.aviso-temporal { margin: 6px 0 10px; padding: 8px 12px; border-radius: 8px; line-height: 1.45; font-size: .9rem;\n  background: color-mix(in srgb, var(--alerta) 12%, var(--tarjeta)); color: var(--texto); border-left: 3px solid var(--alerta); }\n.cabecera-temporal { margin: 0 0 12px; grid-column: 1 / -1; }\n/* v0.51.0 · Mes rápido y simulación con los asientos en edición en los informes */\n.barra-meses { display: flex; flex-wrap: wrap; gap: 4px; margin: 8px 0 4px; }\n.barra-meses button { padding: 4px 9px; font-size: .85rem; min-width: 3.1em; background: transparent; color: var(--texto);\n  border: 1px solid var(--borde); }\n.barra-meses button.activa { background: var(--primario); color: var(--sobre-color); border-color: var(--primario); }\n.rejilla-tres .opcion input[type=\"checkbox\"] { width: auto; flex: none; }   /* la casilla, a su tamaño (no al 100 %) */\n.opciones-informe { display: flex; flex-direction: column; gap: 6px; justify-content: center; }\n.opcion-simulacion { margin: 6px 0 2px; }\n.franja-simulacion { margin: 6px 0 10px; padding: 8px 12px; border-radius: 8px; line-height: 1.45; font-size: .9rem;\n  background: color-mix(in srgb, var(--alerta) 12%, var(--tarjeta)); color: var(--texto); border-left: 3px solid var(--alerta); }\n.franja-simulacion a { color: var(--texto); text-decoration: underline; font-weight: 600; }\n.num-asiento.en-edicion { color: var(--suave); cursor: help; }\n@media print {\n  .barra-meses, .opcion-simulacion, .franja-simulacion a { display: none !important; }\n  .franja-simulacion { background: none; border: 1px solid #000; }\n}\n/* v0.52.0 · Barra superior y tableros */\n.barra-superior { grid-column: 1 / -1; display: flex; gap: 6px; align-items: center; margin: 0 0 12px; padding: 4px 6px;\n  background: var(--tarjeta); border: 1px solid var(--borde); border-radius: 10px; }\n.barra-item { position: relative; }\n.barra-superior button { display: inline-flex; align-items: center; gap: 6px; background: transparent; color: var(--texto);\n  padding: 7px 12px; border-radius: 8px; font-weight: 600; }\n.barra-superior button:hover, .barra-superior button[aria-expanded=\"true\"] { background: color-mix(in srgb, var(--primario) 10%, var(--tarjeta)); }\n.barra-superior button.activa { color: var(--primario); box-shadow: inset 0 -3px 0 var(--primario); }\n.barra-lista { position: absolute; z-index: 30; top: calc(100% + 6px); left: 0; min-width: min(340px, calc(100vw - 32px)); margin: 0;\n  padding: 6px; list-style: none; background: var(--tarjeta); border: 1px solid var(--borde); border-radius: 10px;\n  box-shadow: 0 8px 24px rgba(0,0,0,.14); }\n.barra-lista li { padding: 0; border: 0; display: block; }\n.barra-lista a { display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; border-radius: 8px; color: var(--texto); text-decoration: none; }\n.barra-lista a:hover, .barra-lista a:focus-visible { background: color-mix(in srgb, var(--primario) 10%, var(--tarjeta)); }\n.barra-lista a[aria-current=\"page\"] { box-shadow: inset 3px 0 0 var(--primario); }\n.barra-lista small { color: var(--suave); font-size: .82rem; line-height: 1.35; }\n.tablero { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 16px; }\n@media (min-width: 1100px) { .tablero { grid-template-columns: repeat(2, minmax(0, 1fr)); } .tablero-tarjeta.entera { grid-column: 1 / -1; } }\n.tablero-tarjeta h3 { margin: 0 0 6px; font-size: 1rem; }\n.tablero-cifras { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 12px; }\n.cifra { display: flex; flex-direction: column; gap: 4px; padding: 10px 12px; border: 1px solid var(--borde); border-radius: 10px; }\n.cifra-titulo { color: var(--suave); font-size: .85rem; }\n.cifra-valor { font-size: 1.35rem; font-variant-numeric: tabular-nums; }\n.cifra-variacion { font-size: .85rem; font-variant-numeric: tabular-nums; }\n.cifra-variacion small { color: var(--suave); }\n.cifra .enlace { font-size: .85rem; }\n.grafico .cero { stroke: var(--suave); stroke-width: 1; }\n.grafico .serie-linea { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }\n.grafico .serie-linea.anterior { stroke-width: 1.5; stroke-dasharray: 5 4; opacity: .8; }\n.serie-0 { stroke: var(--primario); fill: var(--primario); }\n.serie-1 { stroke: var(--alerta); fill: var(--alerta); }\n/* v0.53.0: tercera serie (los tres márgenes de Rentabilidad). Magenta: se distingue del azul y del ocre y no se confunde\n   con el verde y el rojo de «bien» y «mal»; la leyenda nombra siempre cada serie */\n:root { --serie-2: #b0177a; }\n@media (prefers-color-scheme: dark) { :root { --serie-2: #ec6cb9; } }\n.serie-2 { stroke: var(--serie-2); fill: var(--serie-2); }\n.grafico.una-serie .serie-linea.anterior { stroke: var(--suave); }\n.grafico .serie-barra.activa { opacity: .75; }\n.grafico .serie-punto { stroke: var(--tarjeta); stroke-width: 2; }\n.leyenda-grafico { display: flex; flex-wrap: wrap; gap: 4px 14px; margin: 6px 0 0; font-size: .85rem; color: var(--suave); }\n.leyenda-grafico .muestra { display: inline-block; width: 14px; height: 10px; border-radius: 2px; vertical-align: middle; background: currentColor; }\n.leyenda-grafico .muestra.serie-0 { background: var(--primario); }\n.leyenda-grafico .muestra.serie-1 { background: var(--alerta); }\n.leyenda-grafico .muestra.serie-2 { background: var(--serie-2); }\n.leyenda-grafico .muestra.anterior { height: 0; border-top: 2px dashed var(--suave); background: none; border-radius: 0; }\n.leyenda-grafico:not(.una-serie) .muestra.anterior.serie-0 { border-top-color: var(--primario); }\n.leyenda-grafico:not(.una-serie) .muestra.anterior.serie-1 { border-top-color: var(--alerta); }\n.leyenda-grafico:not(.una-serie) .muestra.anterior.serie-2 { border-top-color: var(--serie-2); }\n.tablero-salud td small { display: block; }\n/* v0.56.0 · tarjetas de ranking: nombre, barra horizontal e importe con su %; en el móvil, la barra debajo del nombre */\n.rk-resumen { margin: 0 0 8px; font-size: .9rem; }\n.rk-lista { list-style: none; margin: 0; padding: 0; }\n.rk-fila { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 3fr) 12.5rem; gap: 4px 12px; align-items: center;\n           padding: 6px 0; border-bottom: 1px solid var(--borde); flex-direction: initial; }\n.rk-fila:last-child { border-bottom: none; }\n.rk-nombre { overflow-wrap: anywhere; color: var(--texto); font-size: .95rem; }\n.rk-cuenta { color: var(--suave); }\n.rk-barra { height: 10px; background: var(--fondo); border-radius: 5px; overflow: hidden; }\n.rk-barra i { display: block; height: 100%; background: var(--primario); border-radius: 5px; }\n.rk-barra i.negativa { background: var(--alerta); }\n.rk-importe { text-align: right; font-variant-numeric: tabular-nums; font-size: .9rem; color: var(--texto); white-space: nowrap; }\n.rk-importe small { display: block; color: var(--suave); }\n.rk-otra .rk-nombre, .informe tr.rk-otra td:first-child { color: var(--suave); font-style: italic; }\n.rk-otra .rk-barra i { background: var(--suave); }\n.rk-nota { display: block; color: var(--suave); font-size: .8rem; font-style: normal; }\n.rk-fila .rk-nota { grid-column: 1 / -1; }   /* en la lista, a todo el ancho debajo de la fila */\n/* v0.57.0 · lista de control: icono, texto y cifra; el estado también en texto (nunca solo el color) */\n.lista-control { list-style: none; margin: 0; padding: 0; }\n.lista-control li.control { display: grid; grid-template-columns: 1.6rem minmax(0, 1fr) auto; gap: 4px 12px; align-items: start;\n                            padding: 10px 0; border-bottom: 1px solid var(--borde); flex-direction: initial; }\n.lista-control li.control:last-child { border-bottom: none; }\n.control-icono { font-size: 1.15rem; line-height: 1.4; text-align: center; color: var(--suave); }\n.control.ok .control-icono { color: var(--exito); }\n.control.warning .control-icono { color: var(--alerta); }\n.control.error .control-icono { color: var(--error); }\n.control-texto { color: var(--texto); }\n.control-texto strong { font-weight: 600; }\n.control-texto .control-estado { color: var(--suave); font-size: .9rem; }\n.control-texto small { display: block; color: var(--suave); font-size: .85rem; }\n.control-cifra { text-align: right; font-variant-numeric: tabular-nums; color: var(--texto); display: flex; flex-direction: column; gap: 2px; align-items: flex-end; }\n.control-cifra .enlace { font-size: .85rem; }\n.control.na { opacity: .75; }\n/* v0.57.0 · aviso de saldos al revés en el Balance */\n.aviso-reves { margin: 8px 0; padding: 10px 12px; border-radius: 8px; border: 1px solid var(--alerta); background: var(--tarjeta); color: var(--texto); }\n.marca-reves { color: var(--alerta); font-weight: 600; white-space: nowrap; }\n.marca-reves.error, .nota-reves.error { color: var(--error); }\n.nota-reves { display: block; color: var(--alerta); font-size: .85rem; }\n@media (max-width: 600px) {\n  .lista-control li.control { grid-template-columns: 1.6rem minmax(0, 1fr); }\n  .control-cifra { grid-column: 2; align-items: flex-start; text-align: left; }\n  .rk-fila { grid-template-columns: minmax(0, 1fr) auto; }\n  .rk-barra { grid-column: 1 / -1; grid-row: 2; }\n}\n@media print {\n  .barra-superior, .tablero-filtros .rejilla-tres, .leyenda-grafico + .ayuda { display: none !important; }\n  .tablero { display: block; }\n}\n\n/* v0.59.1 · Cuadro de diálogo de confirmación (crear algo): éxito o error, hay que cerrarlo */\n.dialogo-fondo { position: fixed; inset: 0; z-index: 1000; display: grid; place-items: center; padding: 16px;\n                 background: rgba(10, 14, 24, .45); }\n.dialogo { width: min(480px, 100%); max-height: calc(100vh - 32px); overflow: auto; background: var(--tarjeta);\n           color: var(--texto); border-radius: 14px; padding: 20px; box-shadow: 0 18px 48px rgba(0, 0, 0, .3); }\n.dialogo h2 { display: flex; align-items: center; gap: 8px; margin: 0 0 10px; font-size: 1.15rem; }\n.dialogo-exito h2 { color: var(--exito); }\n.dialogo p { margin: 4px 0; }\n.dialogo .caja-error { margin: 0; }\n.dialogo-botones { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 10px; margin-top: 16px; }\n.sr-solo { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n/* v0.59.1 · Empresa sintética generándose */\n.progreso { width: 100%; height: 10px; border-radius: 999px; background: color-mix(in srgb, var(--primario) 14%, var(--tarjeta)); overflow: hidden; }\n.progreso > span { display: block; height: 100%; background: var(--primario); transition: width .3s; }\n", "tests/anomalies.test.js": "import { describe, it, expect } from 'vitest'\nimport { anomalyCounts, anomalyByAccount } from '../src/anomalies.js'\n\n// v0.57.0 · el aviso de saldos al revés del Balance: cada cuenta cuenta en su partida y en las que la contienen\ndescribe('saldos al revés en el Balance', () => {\n  const rows = [\n    { code: 'ACT', parent: null }, { code: 'AC', parent: 'ACT' }, { code: 'AC.I', parent: 'AC' },\n    { code: 'PNP', parent: null }, { code: 'PC', parent: 'PNP' }, { code: 'PC.II.1', parent: 'PC' },\n  ]\n  it('en la partida y en sus partidas superiores, con los imposibles aparte', () => {\n    const m = anomalyCounts(rows, [\n      { line_code: 'AC.I', account_no: '40000002', severity: 'warning' },\n      { line_code: 'PC.II.1', account_no: '57000001', severity: 'error' },\n      { line_code: 'AC.I', account_no: '40000003', severity: 'warning' },\n    ])\n    expect(m['AC.I']).toEqual({ n: 2, errors: 0 })\n    expect(m.ACT).toEqual({ n: 2, errors: 0 })\n    expect(m['PC.II.1']).toEqual({ n: 1, errors: 1 })\n    expect(m.PNP).toEqual({ n: 1, errors: 1 })\n    expect(m['PN']).toBeUndefined()\n  })\n  it('sin cuentas al revés, nada; y una partida que no está en el Balance no se pierde', () => {\n    expect(anomalyCounts(rows, [])).toEqual({})\n    expect(anomalyCounts(rows, null)).toEqual({})\n    expect(anomalyCounts(rows, [{ line_code: 'XX', severity: 'warning' }])).toEqual({ XX: { n: 1, errors: 0 } })\n  })\n  it('por número de cuenta, para marcarla al desplegar', () => {\n    const by = anomalyByAccount([{ account_no: '11300001', note: 'Saldo acreedor.' }])\n    expect(by.get('11300001').note).toBe('Saldo acreedor.')\n    expect(by.get('57200001')).toBeUndefined()\n  })\n})\n\n// v0.59.2 · Al desplegar una partida con sublíneas, cada cuenta dice en cuál se presenta\nimport { accountSubLine } from '../src/anomalies'\ndescribe('cuentas de una partida con sublíneas (v0.59.2)', () => {\n  const rows = [{ code: 'PC.II', label: 'II. Deudas a corto plazo' }, { code: 'PC.II.1', label: '1. Deudas con entidades de crédito' }]\n  it('el banco en descubierto, desplegando «II. Deudas a corto plazo», va a «1. Deudas con entidades de crédito»', () => {\n    expect(accountSubLine({ account_no: '57200000', line_code: 'PC.II.1' }, 'PC.II', rows).label).toBe('1. Deudas con entidades de crédito')\n  })\n  it('desplegando su propia sublínea, no se repite', () => {\n    expect(accountSubLine({ account_no: '57200000', line_code: 'PC.II.1' }, 'PC.II.1', rows)).toBeNull()\n    expect(accountSubLine({ account_no: 'x' }, 'PC.II', rows)).toBeNull()\n  })\n})\n"}

if (!fs.existsSync('package.json') || !fs.existsSync('src')) {
  console.error('✗ Ejecútalo desde la carpeta frontend (donde están package.json y src).'); process.exit(1)
}
for (const [p, texto] of Object.entries(FICHEROS)) {
  const actual = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null
  if (actual !== null && actual.replace(/\r\n/g, '\n') === texto) { console.log('· ' + p + ' ya estaba al día'); continue }
  fs.mkdirSync(path.dirname(p), { recursive: true })
  fs.writeFileSync(p, texto)
  console.log('✓ ' + p)
}
console.log('\n✔ v0.59.2 (web) aplicada. Comprueba con: npx vitest run')
